/**
 * BOVITRACK PRO PWA - MOTOR ZOOTÉCNICO DE CAMPO
 * Cálculos zootécnicos tropicales: GDP, Días Abiertos, DEL, IEP Proyectado y Secado.
 */

const PARAMETROS_ESPECIES = {
  bovino: {
    nombre: 'Bovino (Bos taurus / Bos indicus)',
    diasGestacionMedia: 283,
    diasSecadoRecomendado: 60,
    umbralAlertaSecado: 210, // 7 meses de gestación (210 días)
    pesoBaseUGG: 450
  },
  bufalino: {
    nombre: 'Bufalino (Bubalus bubalis)',
    diasGestacionMedia: 310,
    diasSecadoRecomendado: 60,
    umbralAlertaSecado: 235,
    pesoBaseUGG: 500
  }
};

/**
 * Convierte cualquier cadena de fecha (YYYY-MM-DD o DD/MM/YYYY) u objeto Date en Date válido.
 */
function parsearFechaObjeto(val) {
  if (!val) return new Date(NaN);
  if (val instanceof Date) return val;
  const s = String(val).trim();
  const matchDmy = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if (matchDmy) {
    return new Date(`${matchDmy[3]}-${matchDmy[2].padStart(2, '0')}-${matchDmy[1].padStart(2, '0')}`);
  }
  return new Date(s);
}

/**
 * Calcula la Ganancia Diaria de Peso (GDP) en gramos/día.
 */
function calcularGDP(pesoFinal, pesoInicial, fechaFinal, fechaInicial) {
  if (!pesoFinal || !pesoInicial || !fechaFinal || !fechaInicial) return null;
  const pf = parseFloat(pesoFinal);
  const pi = parseFloat(pesoInicial);
  const df = parsearFechaObjeto(fechaFinal);
  const di = parsearFechaObjeto(fechaInicial);

  const diffMs = df.getTime() - di.getTime();
  const dias = Math.round(diffMs / (1000 * 60 * 60 * 24));
  if (dias <= 0) return null;

  const gdp = ((pf - pi) * 1000) / dias;
  return Math.round(gdp);
}

/**
 * Calcula la Ganancia Diaria de Peso (GDP) de un ejemplar.
 * Si no tiene registro de pesaje anterior, se calcula desde su fecha de nacimiento
 * hasta el día en que se pesó.
 */
function calcularGDPEjemplar({ animal, pesoActual, fechaPesaje }) {
  if (!pesoActual || !fechaPesaje) return null;
  const pAct = parseFloat(pesoActual);
  if (isNaN(pAct) || pAct <= 0) return null;

  // 1. Caso A: Si tiene pesaje previo registrado
  const pPrev = parseFloat(animal?.ultimoPesoKg || animal?.pesoActual);
  const fPrev = animal?.fechaUltimoPesaje || animal?.ultimoPesajeFecha;

  if (pPrev > 0 && fPrev && fPrev !== fechaPesaje) {
    const gdp = calcularGDP(pAct, pPrev, fechaPesaje, fPrev);
    if (gdp !== null) {
      const dPrev = parsearFechaObjeto(fPrev);
      const dPes = parsearFechaObjeto(fechaPesaje);
      const dias = Math.round((dPes.getTime() - dPrev.getTime()) / (1000 * 60 * 60 * 24));
      return { gdp, origen: 'anterior', dias, pesoBase: pPrev, fechaBase: fPrev };
    }
  }

  // 2. Caso B: Si NO tiene pesaje anterior, calcular con fecha de nacimiento
  const fNac = animal?.fechaNacimiento || animal?.fecha_nacimiento;
  if (fNac) {
    const dNac = parsearFechaObjeto(fNac);
    const dPes = parsearFechaObjeto(fechaPesaje);
    const diasVida = Math.round((dPes.getTime() - dNac.getTime()) / (1000 * 60 * 60 * 24));
    if (diasVida > 0) {
      const pesoNac = parseFloat(animal?.pesoAlNacer || animal?.pesoNacimiento || animal?.pesoNacimientoKg || animal?.pesoAlNacerKg || animal?.peso_al_nacer || 0);
      const gananciaKg = pAct - pesoNac;
      const gdp = Math.round((gananciaKg * 1000) / diasVida);
      return { gdp, origen: 'nacimiento', dias: diasVida, pesoBase: pesoNac, fechaBase: fNac };
    }
  }

  return null;
}

/**
 * Calcula los Días Abiertos transcurridos desde el último parto.
 */
function calcularDiasAbiertos(fechaUltimoParto, estadoRepro, fechaCorte = new Date()) {
  if (!fechaUltimoParto) return 0;
  const st = (estadoRepro || '').toLowerCase();
  if (st.includes('preñad') || st.includes('prenad')) return 0;

  const fParto = parsearFechaObjeto(fechaUltimoParto);
  const fRef = parsearFechaObjeto(fechaCorte);
  const dias = Math.floor((fRef.getTime() - fParto.getTime()) / (1000 * 60 * 60 * 24));
  return Math.max(0, dias);
}

/**
 * Calcula los Días en Leche (DEL) en vacas en lactancia.
 */
function calcularDEL(fechaUltimoParto, categoria, fechaCorte = new Date()) {
  if (!fechaUltimoParto) return 0;
  const cat = (categoria || '').toLowerCase();
  if (!cat.includes('ordeño') && !cat.includes('lactante')) return 0;

  const fParto = parsearFechaObjeto(fechaUltimoParto);
  const fRef = parsearFechaObjeto(fechaCorte);
  const dias = Math.floor((fRef.getTime() - fParto.getTime()) / (1000 * 60 * 60 * 24));
  return Math.max(0, dias);
}

/**
 * Calcula el Intervalo Entre Partos (IEP) proyectado en días y meses.
 */
function calcularIEP(diasAbiertos, especie = 'bovino') {
  const conf = PARAMETROS_ESPECIES[especie] || PARAMETROS_ESPECIES.bovino;
  const dias = (diasAbiertos || 0) + conf.diasGestacionMedia;
  return {
    dias,
    meses: parseFloat((dias / 30.417).toFixed(1))
  };
}

/**
 * Calcula la edad en meses cumplidos a partir de fecha_nacimiento.
 */
function calcularEdadMeses(fechaNacimiento, fechaCorte = new Date()) {
  if (!fechaNacimiento) return 0;
  const fn = parsearFechaObjeto(fechaNacimiento);
  const fc = parsearFechaObjeto(fechaCorte);
  if (isNaN(fn.getTime()) || isNaN(fc.getTime())) return 0;
  let m = (fc.getFullYear() - fn.getFullYear()) * 12 + (fc.getMonth() - fn.getMonth());
  if (fc.getDate() < fn.getDate()) m--;
  return Math.max(0, m);
}

/**
 * Fuente Única de Verdad (Single Source of Truth) para la edad en meses de un ejemplar.
 * Prioriza siempre el cálculo automático y en tiempo real desde `fechaNacimiento` / `fecha_nacimiento`
 * registrada en la ficha del animal en la base de datos.
 */
function obtenerEdadMesesAnimal(animal, fechaCorte = new Date()) {
  if (!animal) return 0;
  const fNac = animal.fechaNacimiento || animal.fecha_nacimiento;
  if (fNac) {
    const fn = parsearFechaObjeto(fNac);
    if (!isNaN(fn.getTime())) {
      return calcularEdadMeses(fNac, fechaCorte);
    }
  }
  const edadExplicita = Number(animal.edadMeses ?? animal.edad_meses ?? 0);
  return !isNaN(edadExplicita) && edadExplicita > 0 ? Math.round(edadExplicita) : 0;
}

/**
 * Fuente Única de Verdad (Single Source of Truth) para el peso actual de un ejemplar.
 * Vincula directamente al último registro de pesaje válido o al peso actual almacenado
 * en la ficha técnica del animal en el sistema.
 */
function obtenerPesoActualAnimal(animal, pesajes = null) {
  if (!animal) return 0;
  const listaPesajes = Array.isArray(pesajes)
    ? pesajes
    : (typeof globalThis !== 'undefined' && globalThis.boviApp?.state?.pesajes ? globalThis.boviApp.state.pesajes : null);

  let pesoRecientePesajes = 0;
  let fechaRecientePesajes = 0;

  if (Array.isArray(listaPesajes) && listaPesajes.length > 0) {
    const tagUpper = String(animal.identificacionTag || animal.tag || animal.numero || '').trim().toUpperCase();
    const aId = animal.id;
    const aFinca = animal.fincaId || animal.finca_id;

    for (const p of listaPesajes) {
      if (!p) continue;
      const coincideId = aId && p.animalId === aId;
      const pTag = String(p.tag || p.animalTag || '').trim().toUpperCase();
      const coincideTag = tagUpper && pTag === tagUpper && (!aFinca || !p.fincaId || p.fincaId === aFinca);
      if (coincideId || coincideTag) {
        const valPeso = Number(p.pesoNuevo ?? p.peso ?? p.peso_kg ?? 0);
        if (valPeso > 0) {
          const ts = p.fecha ? parsearFechaObjeto(p.fecha).getTime() : 0;
          const timeVal = !isNaN(ts) && ts > 0 ? ts : 1;
          if (timeVal >= fechaRecientePesajes) {
            fechaRecientePesajes = timeVal;
            pesoRecientePesajes = valPeso;
          }
        }
      }
    }
  }

  const pesoFicha = Number(
    animal.ultimoPesoKg ??
    animal.ultimo_peso_kg ??
    animal.pesoActual ??
    animal.pesoActualKg ??
    animal.peso ??
    0
  );

  if (pesoFicha > 0 && pesoRecientePesajes > 0) {
    const fFicha = animal.fechaUltimoPesaje || animal.fecha_ultimo_pesaje;
    const tsFicha = fFicha ? parsearFechaObjeto(fFicha).getTime() : 0;
    if (!isNaN(tsFicha) && tsFicha > 0 && tsFicha > fechaRecientePesajes) {
      return pesoFicha;
    }
    return pesoRecientePesajes;
  }

  return pesoRecientePesajes > 0 ? pesoRecientePesajes : (pesoFicha > 0 ? pesoFicha : 0);
}

/**
 * Verifica si una hembra gestante debe recibir alerta de secado (7 meses = 210 días).
 */
function verificarSecado7Meses(diasGestacion, especie = 'bovino') {
  const conf = PARAMETROS_ESPECIES[especie] || PARAMETROS_ESPECIES.bovino;
  return diasGestacion >= conf.umbralAlertaSecado && diasGestacion < conf.diasGestacionMedia;
}

/**
 * Formatea cualquier fecha a formato día/mes/año (DD/MM/YYYY).
 * Tolera cadenas ISO (YYYY-MM-DD), fechas con barra o guión, timestamps y objetos Date.
 * Si el valor es nulo, vacío o inválido, retorna el fallback (por defecto '-').
 */
function formatearFecha(val, fallback = '-') {
  if (!val) return fallback;
  if (val instanceof Date) {
    if (isNaN(val.getTime())) return fallback;
    const d = String(val.getDate()).padStart(2, '0');
    const m = String(val.getMonth() + 1).padStart(2, '0');
    const y = val.getFullYear();
    return `${d}/${m}/${y}`;
  }
  const s = String(val).trim();
  if (!s || s === 'null' || s === 'undefined' || s === '-') return fallback;

  // Si ya viene en formato DD/MM/YYYY con 2 dígitos
  const matchDmy = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if (matchDmy) {
    const d = matchDmy[1].padStart(2, '0');
    const m = matchDmy[2].padStart(2, '0');
    const y = matchDmy[3];
    return `${d}/${m}/${y}`;
  }

  // Extraer año, mes, día de cadena ISO (ej: 2026-10-25 o 2026-10-25T14:30:00Z)
  const matchIso = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (matchIso) {
    const y = matchIso[1];
    const m = matchIso[2].padStart(2, '0');
    const d = matchIso[3].padStart(2, '0');
    return `${d}/${m}/${y}`;
  }

  const dt = new Date(s);
  if (!isNaN(dt.getTime())) {
    const d = String(dt.getDate()).padStart(2, '0');
    const m = String(dt.getMonth() + 1).padStart(2, '0');
    const y = dt.getFullYear();
    return `${d}/${m}/${y}`;
  }

  return s;
}

/**
 * Calcula las fechas clave proyectadas a partir de un servicio reproductivo (IA, TE o Monta).
 */
function calcularProyeccionServicio(fechaServicio, especie = 'bovino') {
  if (!fechaServicio) return null;
  const conf = PARAMETROS_ESPECIES[especie] || PARAMETROS_ESPECIES.bovino;
  const fServ = new Date(fechaServicio);

  // 1. Ecografía temprana (30-35 días post-servicio)
  const fEco = new Date(fServ);
  fEco.setDate(fEco.getDate() + 32);

  // 2. Palpación rectal confirmatoria (45-60 días post-servicio)
  const fPalp = new Date(fServ);
  fPalp.setDate(fPalp.getDate() + 60);

  // 3. Fecha probable de parto
  const fParto = new Date(fServ);
  fParto.setDate(fParto.getDate() + conf.diasGestacionMedia);

  // 4. Días transcurridos desde el servicio
  const hoy = new Date();
  const diasDesdeServicio = Math.max(0, Math.floor((hoy.getTime() - fServ.getTime()) / (1000 * 60 * 60 * 24)));

  return {
    fechaServicio,
    diasDesdeServicio,
    fechaEcografiaEstimada: fEco.toISOString().split('T')[0],
    fechaPalpacionEstimada: fPalp.toISOString().split('T')[0],
    fechaPartoEstimada: fParto.toISOString().split('T')[0],
    diasGestacionMedia: conf.diasGestacionMedia
  };
}



