/**
 * ============================================================================
 * GANADERO AD - SERVICIO DE INTEGRACIÓN BIDIRECCIONAL CON WHATSAPP CLOUD API (META)
 * ============================================================================
 *
 * VARIABLES DE ENTORNO REQUERIDAS (Configurar en .env.local o en el panel de Vercel):
 * ----------------------------------------------------------------------------
 * 1. WHATSAPP_VERIFY_TOKEN      -> Token secreto personalizado para verificar el Webhook (GET) en Meta App Dashboard.
 * 2. WHATSAPP_ACCESS_TOKEN      -> Token de acceso permanente o temporal de Meta WhatsApp Cloud API (Bearer Token).
 * 3. WHATSAPP_PHONE_NUMBER_ID   -> ID del número de teléfono de WhatsApp Business en Meta Developers.
 * 4. WHATSAPP_AUTHORIZED_NUMBERS-> Lista separada por comas de números en whitelist (ej: "573001234567,573109876543").
 * 5. SUPABASE_URL               -> URL del proyecto en Supabase (ej: "https://xxxx.supabase.co").
 * 6. SUPABASE_ANON_KEY          -> Anon Key / Service Role Key de Supabase para consultar e insertar registros.
 * ============================================================================
 */

const WA_DEFAULT_SUPABASE_URL = 'https://jucpxyjzmbthplbvzrsj.supabase.co';
const WA_DEFAULT_SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imp1Y3B4eWp6bWJ0aHBsYnZ6cnNqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk3ODExNjMsImV4cCI6MjEwNTM1NzE2M30.EYCHnq6pUNO3cUtD1fRb7l3k-XBbrGtgYmsxkmNzDsA';
const WHATSAPP_STORAGE_KEY = 'bovitrack_whatsapp_cloud_config_v1';

/**
 * Obtiene la configuración de WhatsApp Cloud API almacenada en el programa (localStorage).
 */
function obtenerConfigWhatsAppLocal() {
  try {
    if (typeof localStorage !== 'undefined') {
      const raw = localStorage.getItem(WHATSAPP_STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        return {
          phoneNumberId: String(parsed.phoneNumberId || '').trim(),
          accessToken: String(parsed.accessToken || '').trim(),
          verifyToken: String(parsed.verifyToken || 'ganadero_ad_verify_2026').trim(),
          authorizedNumbers: String(parsed.authorizedNumbers || '573001234567, 573109876543').trim()
        };
      }
    }
  } catch (e) {
    console.warn('[WhatsApp Config] Error leyendo configuración local:', e);
  }
  return {
    phoneNumberId: '',
    accessToken: '',
    verifyToken: 'ganadero_ad_verify_2026',
    authorizedNumbers: '573001234567, 573109876543'
  };
}

/**
 * Guarda la configuración de WhatsApp Cloud API en el programa (localStorage).
 */
function guardarConfigWhatsAppLocal(cfg = {}) {
  const clean = {
    phoneNumberId: String(cfg.phoneNumberId || '').trim(),
    accessToken: String(cfg.accessToken || '').trim(),
    verifyToken: String(cfg.verifyToken || 'ganadero_ad_verify_2026').trim(),
    authorizedNumbers: String(cfg.authorizedNumbers || '').trim(),
    actualizadoEn: new Date().toISOString()
  };
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(WHATSAPP_STORAGE_KEY, JSON.stringify(clean));
    }
  } catch (e) {
    console.warn('[WhatsApp Config] Error guardando configuración local:', e);
  }
  return clean;
}

/**
 * Arreglo base de números de teléfono autorizados (Whitelist).
 * Formato internacional sin el signo '+' (código de país + número, ej. Colombia: 573001234567).
 * Se combina automáticamente con la variable de entorno WHATSAPP_AUTHORIZED_NUMBERS.
 */
const WHITELIST_NUMEROS_AUTORIZADOS = [
  '573001234567',
  '573109876543',
  '573167910000'
];

/**
 * Normaliza un número telefónico dejando únicamente los dígitos (remueve '+', espacios y guiones).
 * @param {string} numero
 * @returns {string}
 */
function normalizarNumeroTelefono(numero) {
  return String(numero || '').replace(/[^\d]/g, '').trim();
}

/**
 * Obtiene la lista consolidada de números autorizados (arreglo en código + variable de entorno).
 * @param {string[]} [whitelistPersonalizada]
 * @returns {string[]}
 */
function obtenerWhitelistAutorizada(whitelistPersonalizada = null) {
  if (Array.isArray(whitelistPersonalizada) && whitelistPersonalizada.length > 0) {
    return whitelistPersonalizada.map(normalizarNumeroTelefono).filter(Boolean);
  }

  if (whitelistPersonalizada && typeof whitelistPersonalizada === 'object' && whitelistPersonalizada.WHATSAPP_AUTHORIZED_NUMBERS) {
    return String(whitelistPersonalizada.WHATSAPP_AUTHORIZED_NUMBERS)
      .split(',')
      .map(normalizarNumeroTelefono)
      .filter(Boolean);
  }

  const envNums = (typeof process !== 'undefined' && process.env && process.env.WHATSAPP_AUTHORIZED_NUMBERS)
    ? String(process.env.WHATSAPP_AUTHORIZED_NUMBERS).split(',').map(normalizarNumeroTelefono).filter(Boolean)
    : [];

  return Array.from(new Set([
    ...WHITELIST_NUMEROS_AUTORIZADOS.map(normalizarNumeroTelefono),
    ...envNums
  ]));
}

/**
 * Verifica si el número del remitente está autorizado en la Whitelist.
 * @param {string} numeroRemitente
 * @param {string[]|object} [whitelistPersonalizada]
 * @returns {boolean}
 */
function verificarNumeroEnWhitelist(numeroRemitente, whitelistPersonalizada = null) {
  const numNorm = normalizarNumeroTelefono(numeroRemitente);
  if (!numNorm) return false;
  const lista = obtenerWhitelistAutorizada(whitelistPersonalizada);
  return lista.includes(numNorm);
}

/**
 * 2. Verificación GET del Webhook de Meta WhatsApp Cloud API.
 * Recibe hub.mode, hub.verify_token y hub.challenge y los compara con WHATSAPP_VERIFY_TOKEN.
 * @param {object} params - Parámetros de query ({ 'hub.mode', 'hub.verify_token', 'hub.challenge' })
 * @param {string|object} [verifyTokenEnv] - Token esperado o process.env con WHATSAPP_VERIFY_TOKEN
 * @returns {{ status: number, body: string }}
 */
function verificarWebhookWhatsApp(params = {}, verifyTokenEnv = undefined) {
  try {
    const mode = params['hub.mode'] ?? params.hub_mode ?? params.mode;
    const token = params['hub.verify_token'] ?? params.hub_verify_token ?? params.verify_token;
    const challenge = params['hub.challenge'] ?? params.hub_challenge ?? params.challenge;

    // ========================================================================
    // COLOCA TU VARIABLE DE ENTORNO AQUÍ: process.env.WHATSAPP_VERIFY_TOKEN
    // ========================================================================
    let tokenEsperado = '';
    if (typeof verifyTokenEnv === 'string') {
      tokenEsperado = verifyTokenEnv;
    } else if (verifyTokenEnv && typeof verifyTokenEnv === 'object') {
      tokenEsperado = verifyTokenEnv.WHATSAPP_VERIFY_TOKEN || '';
    } else if (typeof process !== 'undefined' && process.env) {
      tokenEsperado = process.env.WHATSAPP_VERIFY_TOKEN || '';
    }

    if (mode === 'subscribe' && token && tokenEsperado && token === tokenEsperado) {
      return {
        status: 200,
        body: String(challenge ?? '')
      };
    }

    return {
      status: 403,
      body: 'Forbidden: Token de verificación de WhatsApp inválido.'
    };
  } catch (error) {
    console.error('[WhatsApp Webhook GET] Error en verificación:', error);
    return {
      status: 500,
      body: 'Error interno verificando webhook.'
    };
  }
}

/**
 * 6. Envía un mensaje de texto saliente mediante la API oficial de WhatsApp Cloud de Meta.
 * Endpoint oficial: https://graph.facebook.com/v17.0/${PHONE_NUMBER_ID}/messages
 *
 * @param {string} numeroDestino - Número del destinatario en formato internacional (ej. "573001234567")
 * @param {string} texto - Contenido del mensaje de texto a enviar
 * @param {object} [opciones] - Opciones adicionales para inyección de configuración o fetch en pruebas
 * @returns {Promise<{ ok: boolean, status: number, data?: any, error?: string }>}
 */
async function enviarMensajeWhatsApp(numeroDestino, texto, opciones = {}) {
  try {
    // ========================================================================
    // COLOCA TUS VARIABLES DE ENTORNO DE META AQUÍ:
    // - WHATSAPP_PHONE_NUMBER_ID: ID del teléfono en Meta App Dashboard
    // - WHATSAPP_ACCESS_TOKEN: Token Bearer de acceso a Graph API
    // ========================================================================
    const envRef = opciones.env || (typeof process !== 'undefined' && process.env ? process.env : {});
    const PHONE_NUMBER_ID = opciones.phoneNumberId || envRef.WHATSAPP_PHONE_NUMBER_ID || '';
    const ACCESS_TOKEN = opciones.accessToken || envRef.WHATSAPP_ACCESS_TOKEN || '';
    const fetchFn = opciones.fetchImpl || (typeof fetch !== 'undefined' ? fetch : null);

    if (!PHONE_NUMBER_ID || !ACCESS_TOKEN) {
      throw new Error('Faltan las variables de entorno WHATSAPP_PHONE_NUMBER_ID o WHATSAPP_ACCESS_TOKEN.');
    }
    if (!fetchFn) {
      throw new Error('La función fetch no está disponible en este entorno.');
    }

    const url = `https://graph.facebook.com/v17.0/${PHONE_NUMBER_ID}/messages`;
    const destinatario = normalizarNumeroTelefono(numeroDestino);

    const payload = opciones.usarPlantillaHelloWorld
      ? {
          messaging_product: 'whatsapp',
          to: destinatario,
          type: 'template',
          template: {
            name: opciones.nombrePlantilla || 'hello_world',
            language: { code: opciones.idiomaPlantilla || 'en_US' }
          }
        }
      : {
          messaging_product: 'whatsapp',
          recipient_type: 'individual',
          to: destinatario,
          type: 'text',
          text: {
            preview_url: false,
            body: String(texto || '')
          }
        };

    const response = await fetchFn(url, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${ACCESS_TOKEN}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(payload)
    });

    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      console.error('[WhatsApp Cloud API] Error enviando mensaje:', data);
      return {
        ok: false,
        status: response.status,
        data,
        error: data?.error?.message || `Error HTTP ${response.status} al enviar mensaje por WhatsApp.`
      };
    }

    return {
      ok: true,
      status: response.status,
      data
    };
  } catch (error) {
    console.error('[WhatsApp Cloud API] Excepción en enviarMensajeWhatsApp:', error);
    return {
      ok: false,
      status: 500,
      error: error.message || 'Error desconocido al enviar mensaje de WhatsApp.'
    };
  }
}

/**
 * Crea un adaptador por defecto conectado a Supabase PostgREST para consultar y registrar datos de animales.
 * @param {object} [config]
 */
function crearAdaptadorBaseDatosSupabase(config = {}) {
  // ==========================================================================
  // COLOCA TUS VARIABLES DE ENTORNO DE BASE DE DATOS (SUPABASE) AQUÍ:
  // - SUPABASE_URL: URL REST de tu proyecto Supabase
  // - SUPABASE_ANON_KEY: Clave de API (anon o service_role) de Supabase
  // ==========================================================================
  const supabaseUrl = (
    config.supabaseUrl ||
    (typeof process !== 'undefined' && process.env && (process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL)) ||
    WA_DEFAULT_SUPABASE_URL
  ).replace(/\/+$/, '');

  const supabaseKey = (
    config.supabaseKey ||
    (typeof process !== 'undefined' && process.env && (process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_ANON_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY)) ||
    WA_DEFAULT_SUPABASE_KEY
  ).trim();

  const fetchFn = config.fetchImpl || (typeof fetch !== 'undefined' ? fetch : null);

  const headersBase = {
    'apikey': supabaseKey,
    'Authorization': `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json'
  };

  return {
    /**
     * Consulta un ejemplar por su número/ID (identificacion_tag o id).
     * @param {string} idAnimal
     */
    async consultarAnimalPorId(idAnimal) {
      const tagLimpio = String(idAnimal || '').trim().toUpperCase();
      if (!tagLimpio) return null;

      const query = `identificacion_tag=ilike.${encodeURIComponent(tagLimpio)}&limit=1`;
      const url = `${supabaseUrl}/rest/v1/animales?${query}`;
      const res = await fetchFn(url, { method: 'GET', headers: headersBase });
      if (!res.ok) {
        throw new Error(`Error consultando animal en BD (${res.status})`);
      }
      const filas = await res.json();
      if (Array.isArray(filas) && filas.length > 0) {
        return filas[0];
      }
      return null;
    },

    /**
     * Inserta un nuevo pesaje y actualiza el último peso del animal en la base de datos.
     * @param {{ idAnimal: string, pesoKg: number, fecha?: string, remitente?: string }} datos
     */
    async registrarPesoAnimal({ idAnimal, pesoKg, fecha, remitente }) {
      const tagLimpio = String(idAnimal || '').trim().toUpperCase();
      const fechaHoy = fecha || new Date().toISOString().split('T')[0];
      const animal = await this.consultarAnimalPorId(tagLimpio);

      const fincaId = animal ? animal.finca_id : 'FIN-WHATSAPP';
      const animalId = animal ? animal.id : `ANM-WA-${tagLimpio}`;
      const safeTag = tagLimpio.replace(/[^A-Za-z0-9_-]/g, '_');
      const idPesaje = `PES-${fincaId}-${safeTag}-${fechaHoy}`;

      // 1. Insertar/actualizar registro en la tabla de pesajes (pesajes_animales)
      const registroPesaje = [{
        id: idPesaje,
        finca_id: fincaId,
        animal_id: animalId,
        animal_tag: tagLimpio,
        fecha: fechaHoy,
        peso_kg: Number(pesoKg),
        gdp_calculado: null,
        responsable: remitente ? `WhatsApp (${remitente})` : 'WhatsApp Bot',
        observaciones: `Pesaje registrado vía WhatsApp Cloud API (${pesoKg} kg)`
      }];

      const urlPesajes = `${supabaseUrl}/rest/v1/pesajes_animales?on_conflict=id`;
      const resPesaje = await fetchFn(urlPesajes, {
        method: 'POST',
        headers: { ...headersBase, 'Prefer': 'resolution=merge-duplicates,return=representation' },
        body: JSON.stringify(registroPesaje)
      });

      if (!resPesaje.ok) {
        throw new Error(`Error insertando pesaje en BD (${resPesaje.status})`);
      }

      // 2. Si el animal existe en la tabla animales, actualizar su ultimo_peso_kg y fecha_ultimo_pesaje
      if (animal && animal.id) {
        const urlUpdateAnimal = `${supabaseUrl}/rest/v1/animales?id=eq.${encodeURIComponent(animal.id)}`;
        await fetchFn(urlUpdateAnimal, {
          method: 'PATCH',
          headers: headersBase,
          body: JSON.stringify({
            ultimo_peso_kg: Number(pesoKg),
            fecha_ultimo_pesaje: fechaHoy
          })
        });
      }

      return {
        ok: true,
        idPesaje,
        animalId,
        tag: tagLimpio,
        pesoKg: Number(pesoKg),
        fecha: fechaHoy,
        animalEncontrado: Boolean(animal)
      };
    }
  };
}

/**
 * 5. Procesa los comandos entrantes de texto ("INFO <ID>" y "PESO <ID> <PESO>")
 * interactuando con la base de datos y preparando la respuesta de texto.
 *
 * @param {string} textoMensaje - Texto enviado por el usuario en WhatsApp
 * @param {object} [dbAdapter] - Adaptador de base de datos con consultarAnimalPorId y registrarPesoAnimal
 * @param {string} [remitente] - Número de teléfono del remitente
 * @returns {Promise<{ comando: string, idAnimal?: string, peso?: number, respuestaTexto: string, exito: boolean }>}
 */
async function procesarComandoWhatsApp(textoMensaje, dbAdapter = null, remitente = '') {
  try {
    const textoLimpio = String(textoMensaje || '').trim();
    if (!textoLimpio) {
      return {
        comando: 'VACIO',
        exito: false,
        respuestaTexto: '⚠️ Mensaje vacío. Comandos disponibles:\n• *INFO <ID>* (ej. INFO 045)\n• *PESO <ID> <KG>* (ej. PESO 045 350)'
      };
    }

    const db = dbAdapter || crearAdaptadorBaseDatosSupabase();
    const partes = textoLimpio.split(/\s+/);
    const prefijo = (partes[0] || '').toUpperCase();

    // ========================================================================
    // COMANDO 1: CONSULTA -> "INFO <ID>" (ej. "INFO 045")
    // ========================================================================
    if (prefijo === 'INFO') {
      const idAnimal = (partes[1] || '').trim().toUpperCase();
      if (!idAnimal) {
        return {
          comando: 'INFO',
          exito: false,
          respuestaTexto: '⚠️ Debes indicar el ID del animal. Ejemplo: *INFO 045*'
        };
      }

      const consultarFn = typeof db.consultarAnimalPorId === 'function'
        ? db.consultarAnimalPorId.bind(db)
        : db.consultarAnimalPorTag.bind(db);
      const animal = await consultarFn(idAnimal);
      if (!animal) {
        return {
          comando: 'INFO',
          idAnimal,
          exito: false,
          respuestaTexto: `🔍 No se encontró ningún ejemplar registrado con el ID *${idAnimal}* en la base de datos.`
        };
      }

      const tag = animal.identificacion_tag || animal.identificacionTag || idAnimal;
      const nombre = animal.nombre_alias || animal.nombreAlias || animal.nombre || 'Sin alias';
      const estadoReprod = animal.estado_reproductivo || animal.estadoReproductivo || 'Vacía';
      const diasGest = animal.dias_gestacion_actual ?? animal.diasGestacionActual ?? animal.dias_gestacion ?? animal.diasGestacion ?? 0;
      const peso = animal.ultimo_peso_kg ?? animal.ultimoPesoKg ?? 'S/R';
      const lote = animal.lote || 'General';
      const especie = (animal.especie || 'bovino').toLowerCase() === 'bufalino' ? 'Bufalino 🦬' : 'Vacuno 🐂';
      const detalleGestacion = estadoReprod.toLowerCase().includes('preñada') && diasGest > 0
        ? ` (${diasGest} días de gestación)`
        : '';

      const respuestaTexto =
        `📋 *FICHA DEL ANIMAL ${tag}*\n` +
        `• Nombre: ${nombre}\n` +
        `• Especie: ${especie}\n` +
        `• Estado Reproductivo: *${estadoReprod}*${detalleGestacion}\n` +
        `• Último Peso: *${peso} kg*\n` +
        `• Lote Actual: ${lote}`;

      return {
        comando: 'INFO',
        idAnimal: tag,
        exito: true,
        respuestaTexto
      };
    }

    // ========================================================================
    // COMANDO 2: REGISTRO -> "PESO <ID> <PESO>" (ej. "PESO 045 350")
    // ========================================================================
    if (prefijo === 'PESO') {
      const idAnimal = (partes[1] || '').trim().toUpperCase();
      const pesoStr = (partes[2] || '').replace(',', '.').trim();
      const pesoNumero = parseFloat(pesoStr);

      if (!idAnimal || isNaN(pesoNumero) || pesoNumero <= 0) {
        return {
          comando: 'PESO',
          exito: false,
          respuestaTexto: '⚠️ Formato inválido. Usa: *PESO <ID> <KG>* (Ejemplo: *PESO 045 350*).'
        };
      }

      const fechaHoy = new Date().toISOString().split('T')[0];
      const resultado = db.registrarPesoAnimal.length >= 2
        ? await db.registrarPesoAnimal(idAnimal, pesoNumero, fechaHoy, remitente)
        : await db.registrarPesoAnimal({
            idAnimal,
            pesoKg: pesoNumero,
            fecha: fechaHoy,
            remitente
          });

      const respuestaTexto =
        `✅ *PESAJE REGISTRADO EXITOSAMENTE*\n` +
        `• Animal ID: *${resultado.tag || idAnimal}*\n` +
        `• Nuevo Peso: *${pesoNumero} kg*\n` +
        `• Fecha: ${resultado.fecha || new Date().toISOString().split('T')[0]}`;

      return {
        comando: 'PESO',
        idAnimal,
        peso: pesoNumero,
        exito: true,
        respuestaTexto
      };
    }

    // Comando no reconocido
    return {
      comando: 'DESCONOCIDO',
      exito: false,
      respuestaTexto:
        `🤖 Hola, soy el asistente de *Ganadero AD*.\n` +
        `Comandos disponibles:\n` +
        `1️⃣ *INFO <ID>* → Consultar estado (ej. *INFO 045*)\n` +
        `2️⃣ *PESO <ID> <KG>* → Registrar peso (ej. *PESO 045 350*)`
    };
  } catch (error) {
    console.error('[WhatsApp Bot] Error procesando comando:', error);
    return {
      comando: 'ERROR',
      exito: false,
      respuestaTexto: `❌ Ocurrió un error al procesar tu solicitud en la base de datos: ${error.message}`
    };
  }
}

/**
 * Extrae el mensaje entrante del payload oficial de Meta WhatsApp Cloud API.
 * @param {object} payload
 * @returns {{ from: string, text: string, messageId: string } | null}
 */
function extraerMensajeEntranteMeta(payload) {
  try {
    const entry = payload?.entry?.[0];
    const change = entry?.changes?.[0];
    const value = change?.value;
    const message = value?.messages?.[0];

    if (!message) return null;

    const from = normalizarNumeroTelefono(message.from || '');
    const text = message?.text?.body ? String(message.text.body).trim() : '';
    const messageId = message.id || '';

    return { from, text, messageId };
  } catch (error) {
    console.error('[WhatsApp Webhook] Error extrayendo mensaje del payload:', error);
    return null;
  }
}

/**
 * 3 y 4. Procesa el método POST completo del Webhook de WhatsApp:
 * - Extrae el número del remitente.
 * - Verifica que exista dentro del arreglo de números autorizados (whitelist).
 * - Si NO está en la whitelist, retorna status 200 sin hacer nada.
 * - Si está autorizado, ejecuta el comando (INFO / PESO) contra la base de datos y envía la respuesta por WhatsApp.
 *
 * @param {object} body - Payload JSON entrante enviado por Meta
 * @param {object} [opciones] - Opciones para inyección de dependencias (whitelist, dbAdapter, enviarMensajeFn)
 * @returns {Promise<{ status: number, autorizado: boolean, procesado: boolean, remitente?: string, comando?: string, respuestaTexto?: string }>}
 */
async function procesarWebhookPostWhatsApp(body, opciones = {}) {
  try {
    const mensaje = extraerMensajeEntranteMeta(body);

    // Si es una notificación de estado de entrega/lectura (sin objeto messages), retornar 200 OK
    if (!mensaje || !mensaje.from) {
      return {
        status: 200,
        autorizado: false,
        procesado: false,
        body: { status: 'ok', ignored: true }
      };
    }

    const remitente = mensaje.from;

    // 4. CAPA DE SEGURIDAD: Validar que el número del remitente exista en la Whitelist
    const estaAutorizado = verificarNumeroEnWhitelist(remitente, opciones.whitelist || opciones.env);
    if (!estaAutorizado) {
      console.warn(`[WhatsApp Seguridad] Número no autorizado ignorado: ${remitente}`);
      // Retornar status 200 sin hacer nada para que Meta no reintente el webhook
      return {
        status: 200,
        autorizado: false,
        procesado: false,
        remitente,
        body: { status: 'ignored', ignored: true, reason: 'unauthorized_sender' }
      };
    }

    // 5. Procesar comando ("INFO <ID>" o "PESO <ID> <PESO>")
    const resultadoComando = await procesarComandoWhatsApp(
      mensaje.text,
      opciones.dbAdapter || null,
      remitente
    );

    // 6. Enviar respuesta al usuario mediante la API de Meta
    const enviarFn = opciones.enviarMensajeFn ||
      ((dest, txt) => enviarMensajeWhatsApp(dest, txt, opciones));

    const envio = await enviarFn(remitente, resultadoComando.respuestaTexto);

    return {
      status: 200,
      autorizado: true,
      procesado: true,
      remitente,
      comando: resultadoComando.comando,
      respuestaTexto: resultadoComando.respuestaTexto,
      envioOk: Boolean(envio && envio.ok),
      body: {
        status: 'processed',
        ignored: false,
        comando: resultadoComando.comando,
        remitente,
        envioOk: Boolean(envio && envio.ok)
      }
    };
  } catch (error) {
    console.error('[WhatsApp Webhook POST] Error procesando evento entrante:', error);
    // Siempre retornar 200 a Meta tras capturar el error para evitar bucles de reintentos
    return {
      status: 200,
      autorizado: false,
      procesado: false,
      error: error.message
    };
  }
}


// ============================================================================
// ARCHIVO: frontend/src/ui/AutosuggestAnimales.js
// ============================================================================
/**
 * GANADERO AD - MOTOR UNIVERSAL DE COINCIDENCIAS Y AUTOSUGGEST DE ANIMALES
 * Muestra coincidencias en tiempo real según números o letras digitadas en cualquier
 * módulo de la aplicación (Manga, Traslados, Inventario, Reproducción, Tablas Dinámicas).
 */

function normalizarTextoBusqueda(str) {
  if (!str) return '';
  return String(str)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

/**
 * Busca animales que coincidan con los números o letras digitadas
 * Ordena los resultados por relevancia y exactitud.
 */
function buscarCoincidenciasAnimales(animales, query, maxResultados = 8) {
  if (!Array.isArray(animales) || animales.length === 0) return [];
  if (!query || typeof query !== 'string') return [];

  const qRaw = query.trim();
  if (qRaw.length === 0) return [];

  const qNorm = normalizarTextoBusqueda(qRaw);
  const qDigits = qRaw.replace(/\D/g, ''); // Solo números ingresados

  const resultados = [];

  animales.forEach((a) => {
    const tag = String(a.identificacionTag || a.numero || a.tag || '').trim();
    const tagNorm = normalizarTextoBusqueda(tag);
    const tagDigits = tag.replace(/\D/g, '');

    const alias = String(a.nombreAlias || a.alias || '').trim();
    const aliasNorm = normalizarTextoBusqueda(alias);

    const raza = String(a.raza || '').trim();
    const razaNorm = normalizarTextoBusqueda(raza);

    const categoria = String(a.categoria || '').trim();
    const categoriaNorm = normalizarTextoBusqueda(categoria);

    const lote = String(a.lote || '').trim();
    const loteNorm = normalizarTextoBusqueda(lote);

    const finca = String(a.fincaNombre || a.fincaId || '').trim();
    const fincaNorm = normalizarTextoBusqueda(finca);

    let puntuacion = 0;
    let coincidenciaEncontrada = false;

    // 1. Coincidencia exacta por Arete / Tag
    if (tagNorm === qNorm) {
      puntuacion += 500;
      coincidenciaEncontrada = true;
    } else if (tagNorm.startsWith(qNorm)) {
      puntuacion += 250;
      coincidenciaEncontrada = true;
    } else if (tagNorm.includes(qNorm)) {
      puntuacion += 120;
      coincidenciaEncontrada = true;
    }

    // 2. Coincidencia por Dígitos / Números (Ej: digitando "401" encuentra "BV-401", "201" encuentra "VES-201")
    if (qDigits.length > 0 && tagDigits.length > 0) {
      if (tagDigits === qDigits) {
        puntuacion += 300;
        coincidenciaEncontrada = true;
      } else if (tagDigits.endsWith(qDigits)) {
        puntuacion += 200;
        coincidenciaEncontrada = true;
      } else if (tagDigits.includes(qDigits)) {
        puntuacion += 140;
        coincidenciaEncontrada = true;
      }
    }

    // 3. Coincidencia por Nombre / Alias (Ej: digitando "pal" encuentra "Paloma", "mor" encuentra "Mora")
    if (aliasNorm) {
      if (aliasNorm === qNorm) {
        puntuacion += 350;
        coincidenciaEncontrada = true;
      } else if (aliasNorm.startsWith(qNorm)) {
        puntuacion += 180;
        coincidenciaEncontrada = true;
      } else if (aliasNorm.includes(qNorm)) {
        puntuacion += 100;
        coincidenciaEncontrada = true;
      }
    }

    // 4. Coincidencia por Raza, Categoría o Lote
    if (razaNorm.includes(qNorm)) {
      puntuacion += 50;
      coincidenciaEncontrada = true;
    }
    if (categoriaNorm.includes(qNorm)) {
      puntuacion += 40;
      coincidenciaEncontrada = true;
    }
    if (loteNorm.includes(qNorm)) {
      puntuacion += 30;
      coincidenciaEncontrada = true;
    }
    if (fincaNorm.includes(qNorm)) {
      puntuacion += 20;
      coincidenciaEncontrada = true;
    }

    if (coincidenciaEncontrada) {
      // Priorizar ejemplares del predio activo frente a homónimos de otras fincas
      if (!a._estaEnOtraFinca) {
        puntuacion += 250;
      }
      resultados.push({
        animal: a,
        tag,
        alias,
        raza,
        categoria,
        lote,
        puntuacion
      });
    }
  });

  // Ordenar por puntuación descendente
  resultados.sort((x, y) => y.puntuacion - x.puntuacion);

  return resultados.slice(0, maxResultados).map((r) => r.animal);
}

/**
 * Resalta en texto las letras o números coincidentes
 */
function resaltarCoincidencia(texto, query) {
  if (!texto) return '';
  if (!query) return String(texto);
  const qClean = normalizarTextoBusqueda(query);
  const regex = new RegExp('(' + qClean.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi');
  return String(texto).replace(regex, '<span class="bovi-match-highlight px-1 py-0.2 rounded font-black">$1</span>');
}

/**
 * Conecta el comportamiento de autocompletado en vivo a un elemento input de búsqueda
 */
function conectarAutosuggestAnimales({
  inputElement,
  getAnimales,
  onSeleccionar,
  onTrasladarAFinca,
  onReactivarAnimal,
  onVerFicha = null,
  modoConsulta = false,
  theme = 'emerald', // 'emerald' | 'purple' | 'indigo' | 'amber'
  maxResultados = 8,
  textoVacio = 'Sin coincidencias con esos números o letras'
}) {
  if (!inputElement) return null;

  if (typeof document === 'undefined' || typeof document.createElement !== 'function') {
    return {
      cerrar: () => {},
      actualizarGetAnimales: () => {},
      destruir: () => {}
    };
  }

  const el = typeof inputElement === 'string' ? (document.getElementById ? document.getElementById(inputElement) : null) : inputElement;
  if (!el) return null;

  // Evitar vincular duplicados
  if (el._autosuggestBound) {
    el._autosuggestBound.actualizarGetAnimales(getAnimales);
    return el._autosuggestBound;
  }

  const parent = el.parentElement || el.parentNode;
  if (!parent || typeof parent.appendChild !== 'function') {
    return {
      cerrar: () => {},
      actualizarGetAnimales: () => {},
      destruir: () => {}
    };
  }

  // Colores por tema
  const temas = {
    emerald: {
      border: 'border-emerald-500',
      badgeBg: 'bg-emerald-100 text-emerald-900 border-emerald-300',
      activeItem: 'bg-emerald-50 text-emerald-950 border-emerald-200',
      headerBg: 'bg-emerald-50 border-emerald-100 text-emerald-800'
    },
    purple: {
      border: 'border-purple-500',
      badgeBg: 'bg-purple-100 text-purple-900 border-purple-300',
      activeItem: 'bg-purple-50 text-purple-950 border-purple-200',
      headerBg: 'bg-purple-50 border-purple-100 text-purple-800'
    },
    indigo: {
      border: 'border-indigo-500',
      badgeBg: 'bg-indigo-100 text-indigo-900 border-indigo-300',
      activeItem: 'bg-indigo-50 text-indigo-950 border-indigo-200',
      headerBg: 'bg-indigo-50 border-indigo-100 text-indigo-800'
    },
    amber: {
      border: 'border-amber-500',
      badgeBg: 'bg-amber-100 text-amber-900 border-amber-300',
      activeItem: 'bg-amber-50 text-amber-950 border-amber-200',
      headerBg: 'bg-amber-50 border-amber-100 text-amber-800'
    }
  };
  const tColors = temas[theme] || temas.emerald;

  // Asegurar que el contenedor padre tenga position relative
  if (parent && typeof getComputedStyle === 'function') {
    if (getComputedStyle(parent).position === 'static') {
      parent.style.position = 'relative';
    }
  }

  // Crear menú flotante de sugerencias
  const dropMenu = document.createElement('div');
  dropMenu.className = 'absolute left-0 right-0 top-full mt-1.5 z-50 bg-white rounded-2xl shadow-2xl border-2 ' + tColors.border + ' overflow-hidden hidden';
  dropMenu.style.maxHeight = '340px';
  dropMenu.style.overflowY = 'auto';

  parent.appendChild(dropMenu);

  let animalesCache = getAnimales ? getAnimales() : [];
  let coincidenciasActuales = [];
  let indiceActivo = -1;

  function renderizarMenu(coincidencias, query) {
    coincidenciasActuales = coincidencias;
    indiceActivo = -1;

    if (!coincidencias || coincidencias.length === 0) {
      if (!query || query.trim().length === 0) {
        dropMenu.classList.add('hidden');
        return;
      }
      dropMenu.innerHTML = '<div class="p-3.5 text-center text-xs text-slate-600 font-semibold flex items-center justify-center gap-2"><span>🔍</span> ' + textoVacio + '</div>';
      dropMenu.classList.remove('hidden');
      return;
    }

    let html = '<div class="px-3.5 py-1.5 ' + tColors.headerBg + ' border-b text-[11px] font-black flex items-center justify-between">' +
      '<span class="flex items-center gap-1.5"><span>✨</span> Coincidencias encontradas: ' + coincidencias.length + '</span>' +
      '<span class="text-[10px] font-normal text-slate-600">Clic o Enter para seleccionar</span>' +
      '</div><div class="divide-y divide-slate-100">';

    coincidencias.forEach((a, idx) => {
      const tag = a.identificacionTag || a.numero || a.tag || 'S/N';
      const alias = a.nombreAlias || a.alias || '';
      const especie = (a.especie || '').toLowerCase() === 'bufalino' ? '🦬' : '🐂';
      const raza = a.raza || 'Común';
      const categoria = a.categoria || 'Sin Categoría';
      const lote = a.lote || 'General';
      const peso = a.ultimoPesoKg ? a.ultimoPesoKg + ' Kg' : '';
      const repro = a.estadoReproductivo || '';

      const esEnOtraFinca = Boolean(a._estaEnOtraFinca);
      const esExtraido = Boolean(a._estaExtraido || a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja);
      const esAtenuado = esEnOtraFinca || esExtraido;

      let badgeEstadoExtra = '';
      let mensajeAccion = '';
      if (esEnOtraFinca) {
        badgeEstadoExtra = `<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-amber-100 text-amber-900 border border-amber-300">🏡 En otra finca: ${a._fincaNombre || 'Otra Finca'}</span>`;
        if (modoConsulta) {
          mensajeAccion = `<span class="text-[9px] font-bold text-emerald-700 bg-emerald-50 px-1.5 py-0.5 rounded border border-emerald-200 flex items-center gap-1">🔍 Clic para ver ficha (sin trasladar)</span>`;
        } else {
          mensajeAccion = (typeof onVerFicha === 'function'
            ? `<button type="button" class="btn-autosuggest-ver-ficha text-[9px] font-black text-slate-800 bg-white hover:bg-slate-100 px-2 py-0.5 rounded border border-slate-300 shadow-xs flex items-center gap-1 cursor-pointer mb-0.5" data-index="${idx}" title="Ver ficha técnica sin trasladar el animal">🔍 Ver Ficha (Sin trasladar)</button>`
            : '') +
            `<span class="text-[9px] font-bold text-amber-700 bg-amber-50 px-1.5 py-0.5 rounded border border-amber-200 flex items-center gap-1">🚚 Clic para trasladar</span>`;
        }
      } else if (esExtraido) {
        badgeEstadoExtra = `<span class="px-1.5 py-0.5 rounded text-[10px] font-bold bg-rose-100 text-rose-800 border border-rose-300">🚪 Extraído (${a.motivoBaja || a._motivoExtraido || 'Baja'})</span>`;
        mensajeAccion = modoConsulta
          ? `<span class="text-[9px] font-bold text-slate-700 bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200 flex items-center gap-1">🔍 Clic para ver ficha</span>`
          : `<span class="text-[9px] font-bold text-rose-700 bg-rose-50 px-1.5 py-0.5 rounded border border-rose-200 flex items-center gap-1">🔄 Clic para reactivar</span>`;
      }

      html += `<div class="item-sugerencia-animal bovi-autosuggest-item p-2.5 sm:px-3.5 cursor-pointer transition flex items-center justify-between gap-2.5 text-xs ${esAtenuado ? ' text-slate-600 border-l-4 ' + (esEnOtraFinca ? 'border-amber-400' : 'border-rose-400') : ''}" data-index="${idx}">` +
        `<div class="flex items-center gap-2.5 min-w-0">` +
          `<span class="text-base flex-shrink-0 ${esAtenuado ? 'grayscale ' : ''}">${especie}</span>` +
          `<div class="min-w-0">` +
            `<div class="flex items-center gap-1.5 flex-wrap">` +
              `<span class="font-mono font-black px-2 py-0.5 rounded-lg border text-xs ${esAtenuado ? 'bg-slate-100 text-slate-600 border-slate-300' : tColors.badgeBg}">` +
                resaltarCoincidencia(tag, query) +
              `</span>` +
              (alias ? `<span class="font-black ${esAtenuado ? 'text-slate-600 font-medium' : 'text-slate-800'} truncate">${resaltarCoincidencia(alias, query)}</span>` : '') +
              badgeEstadoExtra +
            `</div>` +
            `<div class="text-[11px] ${esAtenuado ? 'text-slate-600' : 'text-slate-600'} truncate flex items-center gap-1.5 mt-0.5">` +
              `<span>${raza}</span>` +
              `<span>•</span>` +
              `<span>${categoria}</span>` +
              `<span>•</span>` +
              `<span class="text-slate-600 font-mono">Lote: ${lote}</span>` +
            `</div>` +
          `</div>` +
        `</div>` +
        `<div class="text-right flex-shrink-0 flex flex-col items-end gap-1">` +
          (mensajeAccion ? mensajeAccion : '') +
          (peso ? `<span class="font-black font-mono text-xs px-1.5 py-0.5 rounded ${esAtenuado ? 'bg-slate-100 text-slate-600' : 'text-slate-800 bg-slate-100'}">${peso}</span>` : '') +
          (repro ? `<span class="text-[10px] font-bold ${esAtenuado ? 'text-slate-600' : (repro === 'Preñada' ? 'text-emerald-600' : 'text-slate-600')}">${repro}</span>` : '') +
        `</div>` +
      `</div>`;
    });

    html += '</div>';
    dropMenu.innerHTML = html;
    dropMenu.classList.remove('hidden');

    dropMenu.querySelectorAll('.btn-autosuggest-ver-ficha').forEach((btnFicha) => {
      btnFicha.addEventListener('mousedown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        const index = parseInt(btnFicha.getAttribute('data-index'), 10);
        const seleccionado = coincidenciasActuales[index];
        if (seleccionado) {
          const tag = seleccionado.identificacionTag || seleccionado.numero || '';
          el.value = tag;
          dropMenu.classList.add('hidden');
          coincidenciasActuales = [];
          indiceActivo = -1;
          if (typeof onVerFicha === 'function') {
            onVerFicha(seleccionado.id);
          }
          if (typeof onSeleccionar === 'function') {
            onSeleccionar(seleccionado);
          }
        }
      });
    });

    dropMenu.querySelectorAll('.item-sugerencia-animal').forEach((item) => {
      item.addEventListener('mousedown', (e) => {
        if (e.target && e.target.closest && e.target.closest('.btn-autosuggest-ver-ficha')) return;
        e.preventDefault();
        const index = parseInt(item.getAttribute('data-index'), 10);
        const seleccionado = coincidenciasActuales[index];
        if (seleccionado) {
          seleccionar(seleccionado);
        }
      });
    });
  }

  function actualizarResaltadoTeclado() {
    const items = dropMenu.querySelectorAll('.item-sugerencia-animal');
    items.forEach((it, idx) => {
      if (idx === indiceActivo) {
        it.classList.add('bovi-autosuggest-active', 'font-black');
        it.scrollIntoView({ block: 'nearest' });
      } else {
        it.classList.remove('bovi-autosuggest-active', 'font-black');
      }
    });
  }

  function seleccionar(animal) {
    if (!animal) return;
    const tag = animal.identificacionTag || animal.numero || '';

    // En modo consulta (ej. Inventario General, Tablas Dinámicas), abrir la ficha directamente sin trasladar
    if (!modoConsulta) {
      // Si el animal está en otra finca de la misma empresa y estamos en un módulo de ingreso de datos
      if (animal._estaEnOtraFinca) {
        const confirmacion = confirm(`El animal "${tag}" se encuentra registrado en la finca "${animal._fincaNombre || 'otra finca'}".\n\nPara registrar pesaje o ingresar datos es necesario trasladarlo a la finca en la que estás trabajando.\n¿Deseas trasladarlo inmediatamente?\n(Presiona Cancelar si solo deseas consultar su ficha sin trasladarlo)`);
        if (confirmacion && typeof onTrasladarAFinca === 'function') {
          onTrasladarAFinca(animal);
        } else if (!confirmacion && typeof onVerFicha === 'function') {
          onVerFicha(animal.id);
        }
      }
      // Si el animal está extraído (baja por venta o muerte)
      else if (animal._estaExtraido || animal.estadoVida === 'inactivo' || animal.estado === 'inactivo' || animal.motivoBaja) {
        const motivo = animal.motivoBaja || animal._motivoExtraido || 'Baja';
        const confirmacion = confirm(`El animal "${tag}" se encuentra actualmente EXTRAÍDO del hato (Motivo: ${motivo}).\n\n¿Deseas activarlo nuevamente en esta finca?`);
        if (confirmacion && typeof onReactivarAnimal === 'function') {
          onReactivarAnimal(animal);
        }
      }
    }

    el.value = tag;
    dropMenu.classList.add('hidden');
    coincidenciasActuales = [];
    indiceActivo = -1;

    if (typeof onSeleccionar === 'function') {
      onSeleccionar(animal);
    }
  }

  function dispararBusqueda() {
    const q = el.value || '';
    if (!q.trim()) {
      dropMenu.classList.add('hidden');
      return;
    }
    animalesCache = getAnimales ? getAnimales() : [];
    const matches = buscarCoincidenciasAnimales(animalesCache, q, maxResultados);
    renderizarMenu(matches, q);
  }

  el.addEventListener('input', () => {
    dispararBusqueda();
  });

  el.addEventListener('focus', () => {
    if (el.value && el.value.trim().length > 0) {
      dispararBusqueda();
    }
  });

  el.addEventListener('blur', () => {
    setTimeout(() => {
      dropMenu.classList.add('hidden');
    }, 200);
  });

  el.addEventListener('keydown', (e) => {
    if (dropMenu.classList.contains('hidden') || coincidenciasActuales.length === 0) {
      return;
    }

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      indiceActivo = (indiceActivo + 1) % coincidenciasActuales.length;
      actualizarResaltadoTeclado();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      indiceActivo = (indiceActivo - 1 + coincidenciasActuales.length) % coincidenciasActuales.length;
      actualizarResaltadoTeclado();
    } else if (e.key === 'Enter') {
      if (indiceActivo >= 0 && indiceActivo < coincidenciasActuales.length) {
        e.preventDefault();
        if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
        seleccionar(coincidenciasActuales[indiceActivo]);
      } else if (coincidenciasActuales.length > 0) {
        e.preventDefault();
        if (typeof e.stopImmediatePropagation === 'function') e.stopImmediatePropagation();
        const qNorm = normalizarTextoBusqueda(el.value || '');
        const exactMatch = coincidenciasActuales.find(
          (a) => normalizarTextoBusqueda(a.identificacionTag || a.numero || a.tag || '') === qNorm
        );
        seleccionar(exactMatch || coincidenciasActuales[0]);
      }
    } else if (e.key === 'Escape') {
      dropMenu.classList.add('hidden');
    }
  });

  const controlador = {
    cerrar: () => dropMenu.classList.add('hidden'),
    actualizarGetAnimales: (nuevaFn) => { getAnimales = nuevaFn; },
    destruir: () => {
      dropMenu.remove();
      delete el._autosuggestBound;
    }
  };

  el._autosuggestBound = controlador;
  return controlador;
}


// ============================================================================
// ARCHIVO: frontend/src/components/FichaAnimal.js
// ============================================================================
/**
 * GANADERO AD - FICHA ZOOTÉCNICA INDIVIDUAL DEL ANIMAL
 * Visualización completa del ejemplar: genealogía (padre, madre), días de preñez,
 * historial de partos, crías nacidas, pesajes previos, GDP e IEP.
 */



class FichaAnimal {
  constructor({ containerId = 'modal-ficha-animal', onCerrar, onEditar, onEliminar, onTrasladar, onExtraer, onReactivar, getRol }) {
    this.containerId = containerId;
    this.container = typeof document !== 'undefined' ? document.getElementById(containerId) : null;
    this.onCerrar = onCerrar;
    this.onEditar = onEditar;
    this.onEliminar = onEliminar;
    this.onTrasladar = onTrasladar;
    this.onExtraer = onExtraer;
    this.onReactivar = onReactivar;
    this.getRol = getRol;
    this.animal = null;
    this.historialPartos = [];
    this.historialPesajes = [];
    this.historialServicios = [];
    this.modalExtraerAbierto = false;
  }

  abrir(animal, partos = [], pesajes = [], servicios = []) {
    return this.mostrar(animal, partos, pesajes, servicios);
  }

  mostrar(animal, partos = [], pesajes = [], servicios = []) {
    if (!this.container && typeof document !== 'undefined') {
      this.container = document.getElementById(this.containerId || 'modal-ficha-animal');
    }
    this.animal = animal;
    const tag = animal.identificacionTag || animal.numero;
    const tagUpper = String(tag || '').trim().toUpperCase();
    const animalIdStr = String(animal.id || '').trim();

    this.historialPartos = (partos || []).filter((p) => {
      if (!p) return false;
      if (!p.madreTag && !p.madreId) return true; // Si se pasó en la lista sintetizada de este animal
      const pMadreTag = String(p.madreTag || '').trim().toUpperCase();
      const pMadreId = String(p.madreId || '').trim();
      return (tagUpper && pMadreTag === tagUpper) || (animalIdStr && pMadreId === animalIdStr);
    });

    if (Array.isArray(animal.partosPrevios) && animal.partosPrevios.length > 0) {
      animal.partosPrevios.forEach((p) => {
        if (!p) return;
        const yaExiste = this.historialPartos.some((x) => 
          (x.tagCria && p.tagCria && String(x.tagCria).trim().toUpperCase() === String(p.tagCria).trim().toUpperCase()) ||
          ((x.fechaParto || x.fecha) && (p.fechaParto || p.fecha) && (x.fechaParto || x.fecha) === (p.fechaParto || p.fecha))
        );
        if (!yaExiste) {
          this.historialPartos.push(p);
        }
      });
    }

    // Si el animal tiene fechaUltimoParto registrada y no está en historialPartos, incorporarlo
    const fechaUltParto = animal.fechaUltimoParto || animal.ultimoParto;
    if (fechaUltParto) {
      const fNorm = String(fechaUltParto).trim();
      const yaExiste = this.historialPartos.some((x) => String(x.fechaParto || x.fecha || '').trim() === fNorm);
      if (!yaExiste) {
        this.historialPartos.unshift({
          madreId: animal.id,
          madreTag: tag,
          fechaParto: fNorm,
          fecha: fNorm,
          tagCria: animal.tagCria || animal.criaTag || 'Cría Registrada',
          sexoCria: animal.sexoCria || 'hembra',
          pesoAlNacerKg: animal.pesoCria || animal.pesoAlNacerKg || 32,
          tipoParto: animal.tipoParto || 'Normal (Eutócico)',
          observaciones: 'Parto registrado en ficha del animal'
        });
      }
    }
    this.historialPesajes = pesajes.filter(
      (ps) => ps.animalId === animal.id || ps.tag === tag
    );
    this.historialServicios = servicios.filter(
      (s) => s.animalId === animal.id || s.tag === tag || s.animalTag === tag
    );
    if (animal.serviciosReproductivos && animal.serviciosReproductivos.length > 0) {
      animal.serviciosReproductivos.forEach((s) => {
        if (!this.historialServicios.some((x) => x.id === s.id)) {
          this.historialServicios.push(s);
        }
      });
    }
    this.render();
  }

  cerrar() {
    this.animal = null;
    if (this.container) this.container.innerHTML = '';
    if (this.onCerrar) this.onCerrar();
  }

  render() {
    if (!this.container || !this.animal) return;

    const a = this.animal;
    const tag = a.identificacionTag || a.numero;
    const especie = a.especie || 'bovino';
    const edadMeses = calcularEdadMeses(a.fechaNacimiento);
    const edadAnios = (edadMeses / 12).toFixed(1);

    const fParto = a.fechaUltimoParto || a.ultimoParto;
    const diasAbiertos = calcularDiasAbiertos(fParto, a.estadoReproductivo);
    const del = calcularDEL(fParto, a.categoria);
    const iep = calcularIEP(diasAbiertos, especie);

    const estaPrenada = (a.estadoReproductivo || '').toLowerCase().includes('prenad') || (a.estadoReproductivo || '').toLowerCase().includes('preñad');
    const diasG = parseInt(a.diasGestacionActual || a.diasGestacion || 0);

    // Partos y crías registradas
    let partosRegistrados = Array.isArray(this.historialPartos) ? [...this.historialPartos] : [];
    if (fParto) {
      const fPartoNorm = String(fParto).trim();
      const yaExisteParto = partosRegistrados.some((p) => {
        const fp = String(p.fechaParto || p.fecha || '').trim();
        return fp === fPartoNorm;
      });
      if (!yaExisteParto) {
        partosRegistrados.unshift({
          madreId: a.id,
          madreTag: tag,
          fechaParto: fPartoNorm,
          fecha: fPartoNorm,
          tagCria: a.tagCria || a.criaTag || 'Cría Registrada',
          sexoCria: a.sexoCria || 'hembra',
          pesoAlNacerKg: a.pesoCria || a.pesoAlNacerKg || 32,
          tipoParto: a.tipoParto || 'Normal (Eutócico)',
          observaciones: 'Parto registrado en ficha del animal'
        });
        this.historialPartos = partosRegistrados;
      }
    }
    const rol = this.getRol ? this.getRol() : 'consultor';
    const esSoloConsulta = rol === 'consulta' || rol === 'consultor';

    this.container.innerHTML = `
      <div class="fixed inset-0 bg-slate-950/80 backdrop-blur-sm z-50 flex items-center justify-center p-0 sm:p-5 overflow-y-auto">
        <div class="bg-white rounded-none sm:rounded-3xl shadow-2xl border border-slate-200 max-w-4xl w-full h-full sm:h-auto sm:max-h-[92vh] flex flex-col modal-fullscreen-mobile">
          <!-- CABECERA DE LA FICHA -->
          <div class="bovi-module-header p-4 sm:p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 sm:gap-4">
            <div class="flex items-center gap-3 sm:gap-4">
              <div class="w-12 h-12 sm:w-16 sm:h-16 rounded-2xl bg-emerald-600/20 text-emerald-700 border border-emerald-500/30 flex items-center justify-center text-2xl sm:text-3xl font-black shadow-inner shrink-0">
                ${especie === 'bufalino' ? '🦬' : '🐂'}
              </div>
              <div>
                <div class="flex items-center gap-1.5 sm:gap-2 flex-wrap">
                  <span class="text-xl sm:text-2xl font-black font-mono tracking-tight text-slate-800">
                    Arete: ${tag}
                  </span>
                  <span class="px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-bold ${especie === 'bufalino' ? 'bg-amber-500/20 text-amber-700 border border-amber-500/40' : 'bg-blue-500/20 text-blue-700 border border-blue-500/40'}">
                    ${especie === 'bufalino' ? 'Bufalino' : 'Vacuno'}
                  </span>
                  ${a._estaEnOtraFinca ? `
                    <span class="px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-black bg-amber-500/30 text-amber-700 border border-amber-500/50">
                      🏡 En otra finca: ${a._fincaNombre || a.fincaNombre || 'Otra Finca'}
                    </span>
                  ` : ''}
                  ${(a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja) ? `
                    <span class="px-2 py-0.5 rounded-full text-[10px] sm:text-xs font-black bg-rose-500/30 text-rose-700 border border-rose-500/50">
                      🚪 Extraído (${a.motivoBaja || 'Baja'})
                    </span>
                  ` : ''}
                </div>
                <h3 class="text-sm sm:text-base font-bold text-slate-600 mt-0.5">${a.nombreAlias || a.nombre || 'Sin Alias Asignado'}</h3>
                <p class="text-[11px] sm:text-xs text-slate-600 font-mono mt-0.5">${a.raza} • ${a.categoria} • Lote: ${a.lote}${a._fincaNombre || a.fincaNombre ? ` • 🏡 Finca: ${a._fincaNombre || a.fincaNombre}` : ''}</p>
              </div>
            </div>

            <div class="flex items-center gap-2 w-full sm:w-auto justify-between sm:justify-end shrink-0 flex-wrap pt-2 sm:pt-0 border-t sm:border-t-0 border-slate-800">
              ${!esSoloConsulta ? `
                ${(a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja) ? `
                  <button id="btn-ficha-reactivar-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-emerald-600 hover:bg-emerald-500 active:scale-95 text-white font-black text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Activar nuevamente en este hato">
                    <span>🔄</span> Reactivar en el Hato
                  </button>
                ` : `
                  <button id="btn-ficha-extraer-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-amber-600 hover:bg-amber-500 active:scale-95 text-white font-black text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Extraer animal por venta o muerte">
                    <span>🚪</span> Extraer Animal
                  </button>
                  <button id="btn-ficha-trasladar-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-purple-600 hover:bg-purple-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Trasladar este animal a otra finca">
                    <span>🚚</span> Trasladar Finca
                  </button>
                `}
                <button id="btn-ficha-editar-animal" class="flex-1 sm:flex-none px-3.5 py-2.5 sm:py-2 bg-blue-600 hover:bg-blue-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Modificar datos de este ejemplar">
                  <span>✏️</span> Editar
                </button>
                <button id="btn-ficha-eliminar-animal" class="p-2.5 sm:px-3.5 sm:py-2 bg-rose-500/20 hover:bg-rose-500/30 text-rose-700 hover:text-white border border-rose-500/40 font-bold text-xs rounded-xl shadow transition flex items-center justify-center gap-1.5 cursor-pointer" title="Eliminar este animal del inventario">
                  <span>🗑️</span>
                </button>
              ` : ''}
              <button id="btn-cerrar-modal-ficha" class="p-2.5 sm:p-2 rounded-xl bg-slate-800 text-slate-600 hover:text-slate-800 hover:bg-slate-700 transition cursor-pointer" title="Cerrar Ficha">
                ✕
              </button>
            </div>
          </div>

          <!-- CONTENIDO SCROLLEABLE -->
          <div class="p-5 sm:p-6 overflow-y-auto space-y-6 flex-1 text-xs">
            ${(a.estadoVida === 'inactivo' || a.estado === 'inactivo' || a.motivoBaja) ? `
              <div class="bg-rose-50 border-2 border-rose-300 rounded-2xl p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3">
                <div>
                  <div class="flex items-center gap-2">
                    <span class="text-sm font-black text-rose-900">🚪 ANIMAL EXTRAÍDO DEL HATO</span>
                    <span class="px-2 py-0.5 rounded-full font-mono text-[10px] font-black uppercase bg-rose-200 text-rose-900">${a.motivoBaja || 'Baja'}</span>
                  </div>
                  <div class="text-xs text-rose-800 font-medium mt-1">
                    ${(a.motivoBaja || '').toLowerCase() === 'venta' ? `
                      Vendido a: <strong>${a.compradorVenta || 'Comprador no registrado'}</strong> • Valor Venta: <strong>$${(parseFloat(a.valorVenta) || 0).toLocaleString('es-CO')} COP</strong> ${a.pesoVenta ? `• Peso: <strong>${a.pesoVenta} Kg</strong>` : ''} • Fecha: <strong>${formatearFecha(a.fechaBaja)}</strong>
                    ` : `
                      Motivo / Causa de Muerte: <strong>${a.motivoMuerte || 'Causa no especificada'}</strong> • Fecha: <strong>${formatearFecha(a.fechaBaja)}</strong>
                    `}
                  </div>
                </div>
                <button id="btn-ficha-banner-reactivar" class="px-4 py-2 bg-emerald-700 hover:bg-emerald-600 text-white font-black text-xs rounded-xl shadow transition cursor-pointer active:scale-95 shrink-0">
                  <span>🔄</span> Reactivar Ejemplar
                </button>
              </div>
            ` : ''}
            <!-- SECCIÓN 1: DATOS BÁSICOS & GENEALOGÍA -->
            <div>
              <h4 class="font-black text-slate-800 text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
                <span>🧬</span> Identidad y Genealogía (Pedigree)
              </h4>
              <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 bg-slate-50 p-4 rounded-2xl border border-slate-200">
                <div>
                  <span class="block text-slate-600 text-[10px] uppercase font-bold">Fecha Nacimiento</span>
                  <span class="font-bold text-slate-800">${formatearFecha(a.fechaNacimiento, 'No registrada')}</span>
                  <span class="text-[10px] text-slate-600 block">Edad: ${edadMeses} meses (${edadAnios} años)</span>
                </div>
                <div>
                  <span class="block text-slate-600 text-[10px] uppercase font-bold">Sexo</span>
                  <span class="font-bold text-slate-800">${a.sexo === 'hembra' ? '♀️ Hembra' : '♂️ Macho'}</span>
                </div>
                <div>
                  <span class="block text-slate-600 text-[10px] uppercase font-bold">Padre (Toro)</span>
                  <span class="font-bold font-mono text-slate-800 bg-white px-2 py-0.5 rounded border border-slate-200 inline-block mt-0.5">
                    ${a.padreTag || a.padre || 'Desconocido'}
                  </span>
                </div>
                <div>
                  <span class="block text-slate-600 text-[10px] uppercase font-bold">Madre (Vaca)</span>
                  <span class="font-bold font-mono text-slate-800 bg-white px-2 py-0.5 rounded border border-slate-200 inline-block mt-0.5">
                    ${a.madreTag || a.madre || 'Desconocida'}
                  </span>
                </div>
              </div>
            </div>

            <!-- SECCIÓN 2: ESTADO REPRODUCTIVO Y DÍAS DE PREÑEZ -->
            <div>
              <h4 class="font-black text-slate-800 text-sm uppercase tracking-wider mb-3 flex items-center gap-2">
                <span>⚡</span> Estado Reproductivo & Indicadores Zootécnicos
              </h4>
              <div class="grid grid-cols-1 sm:grid-cols-3 gap-3">
                <!-- Tarjeta Preñez -->
                <div class="p-4 rounded-2xl border ${estaPrenada ? 'border-emerald-300 bg-emerald-50/60' : 'border-slate-200 bg-slate-50'}">
                  <span class="text-[10px] font-bold uppercase text-slate-600 block">Diagnóstico Actual</span>
                  <div class="text-base font-black ${estaPrenada ? 'text-emerald-800' : 'text-slate-800'} mt-0.5">
                    ${estaPrenada ? '🟢 Preñada (Gestante)' : (a.estadoReproductivo || 'Vacía')}
                  </div>
                  ${estaPrenada ? `
                    <div class="mt-2 pt-2 border-t border-emerald-200">
                      <span class="text-xs font-bold text-emerald-900">Días de Preñez:</span>
                      <div class="text-xl font-black font-mono text-emerald-700">${diasG} días</div>
                      <div class="w-full h-2 bg-emerald-200 rounded-full mt-1.5 overflow-hidden">
                        <div class="h-full bg-emerald-600 rounded-full" style="width: ${Math.min(100, (diasG / 283) * 100)}%"></div>
                      </div>
                      <span class="text-[10px] text-emerald-700 block mt-1">${(diasG / 30.4).toFixed(1)} meses de gestación (~${283 - diasG} días al parto)</span>
                    </div>
                  ` : `
                    <span class="text-[10px] text-slate-600 block mt-1">Días Abiertos: ${diasAbiertos} días</span>
                  `}
                </div>

                <!-- Tarjeta Intervalo Entre Partos -->
                <div class="p-4 rounded-2xl border border-slate-200 bg-slate-50">
                  <span class="text-[10px] font-bold uppercase text-slate-600 block">Intervalo Entre Partos (IEP)</span>
                  <div class="text-base font-black text-slate-800 mt-0.5">
                    ${fParto ? `${iep.dias} Días` : 'Primerizo / Sin registro'}
                  </div>
                  <span class="text-[10px] text-slate-600 block mt-1">
                    ${fParto ? `Proyección: ${iep.meses} Meses entre partos` : 'Sin partos previos'}
                  </span>
                  <div class="mt-2 text-[10px] text-slate-600">
                    Último Parto: <strong>${formatearFecha(fParto, 'No registra')}</strong>
                  </div>
                </div>

                <!-- Tarjeta Productiva (Peso & Leche) -->
                <div class="p-4 rounded-2xl border border-slate-200 bg-slate-50">
                  <span class="text-[10px] font-bold uppercase text-slate-600 block">Producción Actual</span>
                  <div class="text-base font-black text-slate-800 mt-0.5">
                    ${a.ultimoPesoKg || a.pesoActual ? `${a.ultimoPesoKg || a.pesoActual} kg` : '-'}
                  </div>
                  <span class="text-[10px] text-emerald-700 font-bold block mt-1">
                    GDP: ${a.gdpPromedioGDia !== undefined ? `${a.gdpPromedioGDia} g/d` : (a.gdpActual ? `${a.gdpActual} g/d` : 'No calculada')}
                  </span>
                  <div class="mt-2 text-[10px] text-slate-600">
                    Leche: <strong>${a.promedioLecheDiariaL || a.produccionLecheDiaria || 0} L/día</strong> ${del > 0 ? `(${del} DEL)` : ''}
                  </div>
                </div>
              </div>
            </div>

            <!-- SECCIÓN 3: HISTORIAL DE PARTOS Y CRÍAS -->
            <div>
              <div class="flex justify-between items-center mb-3">
                <h4 class="font-black text-slate-800 text-sm uppercase tracking-wider flex items-center gap-2">
                  <span>🍼</span> Historial de Partos y Crías (${partosRegistrados.length})
                </h4>
              </div>

              ${partosRegistrados.length > 0 ? `
                <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                  <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                      <tr>
                        <th class="p-2.5">Fecha de Parto</th>
                        <th class="p-2.5">Tag de la Cría</th>
                        <th class="p-2.5">Sexo Cría</th>
                        <th class="p-2.5 text-right">Peso al Nacer</th>
                        <th class="p-2.5">Tipo de Parto</th>
                        <th class="p-2.5">Observaciones</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      ${partosRegistrados.map((p) => `
                        <tr class="hover:bg-slate-50">
                          <td class="p-2.5 font-bold">${formatearFecha(p.fechaParto || p.fecha)}</td>
                          <td class="p-2.5 font-mono font-black text-emerald-800">${p.tagCria || p.tagCriaGenerado || p.criaId || 'Cría Registrada'}</td>
                          <td class="p-2.5">${(p.sexoCria || '').toLowerCase().includes('hembra') ? '♀️ Hembra' : '♂️ Macho'}</td>
                          <td class="p-2.5 text-right font-mono font-bold">${p.pesoAlNacerKg || p.pesoCria || p.pesoNacimientoKg || 32} kg</td>
                          <td class="p-2.5">${p.tipoParto || 'Normal (Eutócico)'}</td>
                          <td class="p-2.5 text-slate-600">${p.observaciones || 'Sin novedad'}</td>
                        </tr>
                      `).join('')}
                    </tbody>
                  </table>
                </div>
              ` : `
                <div class="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-600 text-xs">
                  Este ejemplar no tiene partos o crías registradas en su historial.
                </div>
              `}
            </div>

            <!-- SECCIÓN 4: HISTORIAL DE SERVICIOS REPRODUCTIVOS (IA / TE / MONTA) -->
            ${(a.sexo || '').toLowerCase() === 'hembra' ? `
              <div>
                <div class="flex justify-between items-center mb-3">
                  <h4 class="font-black text-slate-800 text-sm uppercase tracking-wider flex items-center gap-2">
                    <span>🧬</span> Historial de Inseminaciones, Embriones y Montas (${this.historialServicios.length})
                  </h4>
                </div>

                ${this.historialServicios.length > 0 ? `
                  <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                    <table class="w-full text-left text-xs">
                      <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                        <tr>
                          <th class="p-2.5">Fecha</th>
                          <th class="p-2.5">Modalidad</th>
                          <th class="p-2.5">Toro / Pajilla / Donadora</th>
                          <th class="p-2.5">Técnico / Responsable</th>
                          <th class="p-2.5">Protocolo / Observación</th>
                          <th class="p-2.5">Resultado</th>
                        </tr>
                      </thead>
                      <tbody class="divide-y divide-slate-100">
                        ${this.historialServicios.map((s) => {
                          let badgeTipo = 'bg-indigo-100 text-indigo-800';
                          let nomTipo = '💉 Inseminación Artificial';
                          if (s.tipo === 'transferencia_embriones') {
                            badgeTipo = 'bg-purple-100 text-purple-800';
                            nomTipo = '🔬 Transf. Embriones';
                          } else if (s.tipo === 'monta_natural') {
                            badgeTipo = 'bg-amber-100 text-amber-900';
                            nomTipo = '🐂 Servicio con Toro';
                          }

                          const st = s.resultado || 'Pendiente Chequeo';
                          let badgeSt = 'bg-amber-100 text-amber-800 border-amber-300';
                          if (st === 'Preñada Confirmada') badgeSt = 'bg-emerald-100 text-emerald-800 border-emerald-300';
                          if (st === 'Vacía / Repitió') badgeSt = 'bg-rose-100 text-rose-800 border-rose-300';

                          return `
                            <tr class="hover:bg-slate-50">
                              <td class="p-2.5 font-bold font-mono text-slate-800">${formatearFecha(s.fecha)}</td>
                              <td class="p-2.5">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${badgeTipo}">
                                  ${nomTipo}
                                </span>
                              </td>
                              <td class="p-2.5 font-bold text-slate-800">
                                ${s.reproductor || '-'}
                                ${s.donadora ? `<span class="block text-[10px] text-purple-700 font-normal">Donadora: ${s.donadora}</span>` : ''}
                              </td>
                              <td class="p-2.5 text-slate-600">${s.tecnico || '-'}</td>
                              <td class="p-2.5 text-slate-600">${s.protocolo || s.observaciones || '-'}</td>
                              <td class="p-2.5">
                                <span class="px-2 py-0.5 rounded-full text-[10px] font-bold border ${badgeSt}">
                                  ${st}
                                </span>
                              </td>
                            </tr>
                          `;
                        }).join('')}
                      </tbody>
                    </table>
                  </div>
                ` : `
                  <div class="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-600 text-xs">
                    No se registran servicios reproductivos (IA, TE o Monta) para esta hembra.
                  </div>
                `}
              </div>
            ` : ''}

            <!-- SECCIÓN 5: HISTORIAL DE PESAJES -->
            <div>
              <div class="flex justify-between items-center mb-3">
                <h4 class="font-black text-slate-800 text-sm uppercase tracking-wider flex items-center gap-2">
                  <span>⚖️</span> Trazabilidad de Pesajes y Ganancia Ponderal (${this.historialPesajes.length})
                </h4>
              </div>

              <div class="bg-slate-50 p-4 rounded-2xl border border-slate-200 mb-3">
                <div class="flex justify-between items-center text-xs text-slate-700">
                  <span>Último Pesaje Registrado: <strong>${formatearFecha(a.fechaUltimoPesaje || a.ultimoPesajeFecha, 'Reciente')}</strong></span>
                  <span class="font-mono font-black text-base text-emerald-800">${a.ultimoPesoKg || a.pesoActual || 0} kg</span>
                </div>
                <div class="mt-2 text-[11px] text-slate-600">
                  Condición corporal actual evaluada: <strong>${a.condicionCorporal || '3.5 (Óptima)'}</strong>
                </div>
              </div>

              ${this.historialPesajes.length > 0 ? `
                <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                  <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                      <tr>
                        <th class="p-2.5">Fecha</th>
                        <th class="p-2.5 text-right">Peso Registrado</th>
                        <th class="p-2.5 text-right">GDP</th>
                        <th class="p-2.5">Lote / Ubicación</th>
                        <th class="p-2.5">Responsable</th>
                        <th class="p-2.5">Observaciones</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      ${this.historialPesajes.slice().sort((p1, p2) => (p2.fecha || '').localeCompare(p1.fecha || '')).map((ps) => {
                        const pNum = ps.pesoNuevo || ps.peso || 0;
                        return `
                          <tr class="hover:bg-slate-50">
                            <td class="p-2.5 font-bold font-mono text-slate-800">${formatearFecha(ps.fecha)}</td>
                            <td class="p-2.5 text-right font-mono font-black text-emerald-800">${pNum} kg</td>
                            <td class="p-2.5 text-right font-mono font-bold ${ps.gdp ? (Number(ps.gdp) >= 0 ? 'text-emerald-700' : 'text-rose-700') : 'text-slate-600'}">
                              ${ps.gdp ? `${ps.gdp > 0 ? '+' : ''}${ps.gdp} g/d` : '-'}
                            </td>
                            <td class="p-2.5 font-mono text-slate-600">${ps.lote || a.lote || 'General'}</td>
                            <td class="p-2.5 text-slate-600">${ps.responsable || 'Báscula'}</td>
                            <td class="p-2.5 text-slate-600">${ps.observaciones || '-'}</td>
                          </tr>
                        `;
                      }).join('')}
                    </tbody>
                  </table>
                </div>
              ` : ''}
            </div>

            <!-- SECCIÓN 6: HISTORIAL DE PALPACIONES, CONTROLES DE LECHE Y LABORES DE CAMPO -->
            <div>
              <div class="flex justify-between items-center mb-3">
                <h4 class="font-black text-slate-800 text-sm uppercase tracking-wider flex items-center gap-2">
                  <span>🩺</span> Palpaciones, Controles de Leche, Destetes y Bitácora (${(a.historialEventos || []).length})
                </h4>
              </div>

              ${Array.isArray(a.historialEventos) && a.historialEventos.length > 0 ? `
                <div class="overflow-x-auto border border-slate-200 rounded-2xl">
                  <table class="w-full text-left text-xs">
                    <thead class="bg-slate-100 uppercase font-bold text-slate-700 text-[10px]">
                      <tr>
                        <th class="p-2.5">Fecha</th>
                        <th class="p-2.5">Labor / Evento</th>
                        <th class="p-2.5">Resultado / Detalle Zootécnico</th>
                        <th class="p-2.5">Responsable / Profesional</th>
                      </tr>
                    </thead>
                    <tbody class="divide-y divide-slate-100">
                      ${a.historialEventos.map((ev) => {
                        let badgeTipo = 'bg-slate-100 text-slate-800';
                        let tituloTipo = ev.tipo || 'Evento';
                        let detalleEv = '';

                        if (ev.tipo === 'palpacion') {
                          badgeTipo = 'bg-rose-100 text-rose-800 border border-rose-200';
                          tituloTipo = '🩺 Palpación Ginecológica';
                          detalleEv = `<strong>${ev.resultado || 'Diagnóstico'}</strong> ${ev.diasGestacion ? `• ${ev.diasGestacion} días gestación` : ''} ${ev.diagnostico || ev.estructuraOvario ? `(${ev.diagnostico || ev.estructuraOvario})` : ''}`;
                        } else if (ev.tipo === 'pesaje_leche') {
                          badgeTipo = 'bg-cyan-100 text-cyan-800 border border-cyan-200';
                          tituloTipo = '🥛 Control Lechero';
                          detalleEv = `Producción: <strong>${ev.litros || 0} L</strong> ${ev.jornada ? `• Jornada ${ev.jornada}` : ''} ${ev.grasa ? `• Grasa: ${ev.grasa}%` : ''} ${ev.proteina ? `• Proteína: ${ev.proteina}%` : ''}`;
                        } else if (ev.tipo === 'destete') {
                          badgeTipo = 'bg-orange-100 text-orange-800 border border-orange-200';
                          tituloTipo = '🌾 Destete';
                          const pTern = ev.pesoTernero || ev.pesoDestete || 0;
                          const pVaca = ev.pesoMadre || ev.pesoVaca || 0;
                          const relTxt = (ev.madreTag || ev.criaTag) ? `• Madre: <strong>${ev.madreTag || 'S/D'}</strong> ↔ Cría: <strong>${ev.criaTag || 'S/D'}</strong>` : '';
                          detalleEv = `Destete completado ${pTern ? `• Peso Ternero: <strong>${pTern} kg</strong>` : ''} ${pVaca ? `• Peso Vaca: <strong>${pVaca} kg</strong>` : ''} ${relTxt} ${ev.loteDestino ? `• Lote: <strong>${ev.loteDestino}</strong>` : ''}`;
                        } else if (ev.tipo === 'parto') {
                          badgeTipo = 'bg-amber-100 text-amber-800 border border-amber-200';
                          tituloTipo = '🍼 Parto';
                          detalleEv = `Cría: <strong>${ev.criaTag || 'S/N'}</strong> (${ev.sexoCria || 'Cría'}) ${ev.pesoAlNacerKg ? `• Peso al nacer: ${ev.pesoAlNacerKg} kg` : ''} ${ev.tipoParto ? `• Parto: ${ev.tipoParto}` : ''}`;
                        } else {
                          detalleEv = ev.detalle || ev.observaciones || '-';
                        }

                        return `
                          <tr class="hover:bg-slate-50">
                            <td class="p-2.5 font-bold font-mono text-slate-800 whitespace-nowrap">${formatearFecha(ev.fecha)}</td>
                            <td class="p-2.5 whitespace-nowrap">
                              <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${badgeTipo}">
                                ${tituloTipo}
                              </span>
                            </td>
                            <td class="p-2.5 text-slate-700">${detalleEv}</td>
                            <td class="p-2.5 text-slate-600 whitespace-nowrap">${ev.responsable || ev.veterinario || 'Veterinario / Operario'}</td>
                          </tr>
                        `;
                      }).join('')}
                    </tbody>
                  </table>
                </div>
              ` : `
                <div class="p-6 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-600 text-xs">
                  No se registran eventos adicionales de campo (palpaciones, leche o destetes) para este ejemplar.
                </div>
              `}
            </div>
          </div>

          <!-- PIE DE LA FICHA -->
          <div class="bg-slate-50 p-4 border-t border-slate-200 flex flex-col sm:flex-row justify-between items-center gap-3">
            <div>
              ${!esSoloConsulta ? `
                <button id="btn-ficha-editar-animal-footer" class="px-4 py-2 bg-blue-600 hover:bg-blue-500 active:scale-95 text-white font-bold text-xs rounded-xl shadow transition flex items-center gap-1.5 cursor-pointer">
                  <span>✏️</span> Modificar Datos de este Animal
                </button>
              ` : '<span class="text-xs text-slate-600 italic">Modo sólo lectura (Consultor)</span>'}
            </div>
            <button id="btn-cerrar-ficha-footer" class="px-5 py-2 bg-slate-900 hover:bg-slate-800 text-slate-800 font-bold text-xs rounded-xl shadow transition cursor-pointer">
              Cerrar Ficha
            </button>
          </div>
        </div>

        <!-- MODAL DE EXTRACCIÓN (VENTA O MUERTE) -->
        ${this.modalExtraerAbierto ? this.renderModalExtraer() : ''}
      </div>
    `;

    this.attachEvents();
  }

  renderModalExtraer() {
    const a = this.animal;
    const tag = a.identificacionTag || a.numero;
    const hoy = new Date().toISOString().split('T')[0];

    return `
      <div id="modal-extraer-animal" class="fixed inset-0 bg-slate-950/85 backdrop-blur-sm z-[60] flex items-center justify-center p-3 sm:p-5">
        <div class="bg-white rounded-3xl shadow-2xl border border-slate-200 max-w-lg w-full overflow-hidden animate-fadeIn">
          <div class="bg-gradient-to-r from-amber-900 via-amber-800 to-amber-900 text-slate-800 p-5 flex justify-between items-center">
            <div class="flex items-center gap-3">
              <span class="text-2xl">🚪</span>
              <div>
                <h3 class="font-black text-base">Extraer Animal: ${tag}</h3>
                <p class="text-xs text-amber-700 mt-0.5">Registre la salida del ejemplar por venta o muerte.</p>
              </div>
            </div>
            <button id="btn-cerrar-modal-extraer" class="text-amber-700 hover:text-slate-800 text-lg font-bold cursor-pointer">✕</button>
          </div>

          <div class="p-5 sm:p-6 space-y-4 text-xs">
            <div>
              <label class="block font-black text-slate-800 uppercase tracking-wider text-[11px] mb-2">Motivo de Extracción:</label>
              <div class="grid grid-cols-2 gap-3">
                <label class="flex items-center justify-center gap-2 p-3 rounded-2xl border-2 border-emerald-500 bg-emerald-50/60 font-black cursor-pointer text-emerald-950">
                  <input type="radio" name="radio-motivo-extraccion" value="Venta" checked class="text-emerald-600">
                  <span>💰 Por Venta</span>
                </label>
                <label class="flex items-center justify-center gap-2 p-3 rounded-2xl border-2 border-slate-200 bg-slate-50 font-black cursor-pointer text-slate-800">
                  <input type="radio" name="radio-motivo-extraccion" value="Muerte" class="text-rose-600">
                  <span>💀 Por Muerte</span>
                </label>
              </div>
            </div>

            <!-- Campos para Venta -->
            <div id="seccion-extraer-venta" class="space-y-3 bg-amber-50/60 p-4 rounded-2xl border border-amber-200">
              <div>
                <label class="block font-bold text-slate-800 mb-1">¿A quién se le vendió? (Comprador):</label>
                <input type="text" id="input-extraer-comprador" placeholder="Ej. Frigorífico, Subasta, Don Carlos..." class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold outline-none text-xs">
              </div>
              <div class="grid grid-cols-2 gap-3">
                <div>
                  <label class="block font-bold text-slate-800 mb-1">Valor Venta ($ COP):</label>
                  <input type="number" id="input-extraer-valor" placeholder="Ej. 3500000" class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold font-mono text-emerald-800 outline-none text-xs">
                </div>
                <div>
                  <label class="block font-bold text-slate-800 mb-1">Peso Venta (kg):</label>
                  <input type="number" step="0.5" id="input-extraer-peso" value="${a.ultimoPesoKg || ''}" placeholder="Ej. 480" class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold font-mono outline-none text-xs">
                </div>
              </div>
              <p class="text-[10px] text-amber-900 font-medium">💡 Este valor se sumará a los ingresos financieros de la finca.</p>
            </div>

            <!-- Campos para Muerte -->
            <div id="seccion-extraer-muerte" class="space-y-3 bg-rose-50/60 p-4 rounded-2xl border border-rose-200 hidden">
              <div>
                <label class="block font-bold text-slate-800 mb-1">Cuadro de Motivo / Causa de la Muerte *:</label>
                <textarea id="input-extraer-causa-muerte" rows="3" placeholder="Describa en este cuadro el motivo o causa de la muerte (ej. Timpanismo agudo, picadura de serpiente, infarto, enfermedad, accidente, diagnóstico veterinario)..." class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-medium outline-none text-xs resize-none focus:border-rose-500"></textarea>
              </div>
            </div>

            <div class="grid grid-cols-2 gap-3">
              <div>
                <label class="block font-bold text-slate-800 mb-1">Fecha del Suceso:</label>
                <input type="date" id="input-extraer-fecha" value="${hoy}" class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 font-bold outline-none text-xs">
              </div>
              <div>
                <label class="block font-bold text-slate-800 mb-1">Observaciones:</label>
                <input type="text" id="input-extraer-obs" placeholder="Detalles de la baja..." class="w-full px-3 py-2 bg-white rounded-xl border border-slate-300 text-xs outline-none">
              </div>
            </div>

            <div class="flex justify-end gap-2 pt-2 border-t border-slate-100">
              <button id="btn-cancelar-modal-extraer" class="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs transition cursor-pointer">
                Cancelar
              </button>
              <button id="btn-confirmar-modal-extraer" class="px-5 py-2 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-xl text-xs shadow-md transition cursor-pointer active:scale-95">
                Confirmar Extracción
              </button>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  attachEvents() {
    const btnCerrar = this.container.querySelector('#btn-cerrar-modal-ficha');
    if (btnCerrar) btnCerrar.addEventListener('click', () => this.cerrar());

    const btnFooter = this.container.querySelector('#btn-cerrar-ficha-footer');
    if (btnFooter) btnFooter.addEventListener('click', () => this.cerrar());

    const btnEditar = this.container.querySelector('#btn-ficha-editar-animal');
    if (btnEditar) {
      btnEditar.addEventListener('click', () => {
        if (this.onEditar) this.onEditar(this.animal);
      });
    }

    const btnEditarFooter = this.container.querySelector('#btn-ficha-editar-animal-footer');
    if (btnEditarFooter) {
      btnEditarFooter.addEventListener('click', () => {
        if (this.onEditar) this.onEditar(this.animal);
      });
    }

    const btnEliminar = this.container.querySelector('#btn-ficha-eliminar-animal');
    if (btnEliminar) {
      btnEliminar.addEventListener('click', () => {
        const tag = this.animal.identificacionTag || this.animal.numero;
        if (confirm(`¿Estás seguro de eliminar permanentemente al ejemplar ${tag} del inventario?`)) {
          if (this.onEliminar) this.onEliminar(this.animal.id);
        }
      });
    }

    const btnTrasladar = this.container.querySelector('#btn-ficha-trasladar-animal');
    if (btnTrasladar) {
      btnTrasladar.addEventListener('click', () => {
        if (this.onTrasladar) this.onTrasladar(this.animal);
      });
    }

    // Botón abrir modal de extracción
    const btnExtraer = this.container.querySelector('#btn-ficha-extraer-animal');
    if (btnExtraer) {
      btnExtraer.addEventListener('click', () => {
        this.modalExtraerAbierto = true;
        this.render();
      });
    }

    // Botones de reactivación
    const ejecutarReactivacion = () => {
      const tag = this.animal.identificacionTag || this.animal.numero;
      if (confirm(`¿Deseas activar nuevamente al animal ${tag} en este hato?`)) {
        if (this.onReactivar) {
          this.onReactivar(this.animal);
          this.cerrar();
        }
      }
    };

    const btnReactivar = this.container.querySelector('#btn-ficha-reactivar-animal');
    if (btnReactivar) btnReactivar.addEventListener('click', ejecutarReactivacion);

    const btnBannerReactivar = this.container.querySelector('#btn-ficha-banner-reactivar');
    if (btnBannerReactivar) btnBannerReactivar.addEventListener('click', ejecutarReactivacion);

    // Eventos dentro del modal de extracción
    if (this.modalExtraerAbierto) {
      const btnCerrarExtraer = this.container.querySelector('#btn-cerrar-modal-extraer');
      const btnCancelExtraer = this.container.querySelector('#btn-cancelar-modal-extraer');
      const cerrarModalExtraer = () => {
        this.modalExtraerAbierto = false;
        this.render();
      };
      if (btnCerrarExtraer) btnCerrarExtraer.addEventListener('click', cerrarModalExtraer);
      if (btnCancelExtraer) btnCancelExtraer.addEventListener('click', cerrarModalExtraer);

      const secVenta = this.container.querySelector('#seccion-extraer-venta');
      const secMuerte = this.container.querySelector('#seccion-extraer-muerte');
      const radios = this.container.querySelectorAll('input[name="radio-motivo-extraccion"]');

      radios.forEach((r) => {
        r.addEventListener('change', () => {
          if (r.value === 'Venta') {
            if (secVenta) secVenta.classList.remove('hidden');
            if (secMuerte) secMuerte.classList.add('hidden');
          } else {
            if (secVenta) secVenta.classList.add('hidden');
            if (secMuerte) secMuerte.classList.remove('hidden');
          }
        });
      });

      const btnConfirmarExtraer = this.container.querySelector('#btn-confirmar-modal-extraer');
      if (btnConfirmarExtraer) {
        btnConfirmarExtraer.addEventListener('click', () => {
          let motivo = 'Venta';
          radios.forEach((rd) => { if (rd.checked) motivo = rd.value; });

          const fecha = this.container.querySelector('#input-extraer-fecha')?.value || new Date().toISOString().split('T')[0];
          const observaciones = (this.container.querySelector('#input-extraer-obs')?.value || '').trim();

          const datos = {
            motivo,
            fecha,
            observaciones
          };

          if (motivo === 'Venta') {
            const comprador = (this.container.querySelector('#input-extraer-comprador')?.value || '').trim() || 'Cliente Particular';
            const valorVenta = parseFloat(this.container.querySelector('#input-extraer-valor')?.value) || 0;
            const pesoVenta = parseFloat(this.container.querySelector('#input-extraer-peso')?.value) || this.animal.ultimoPesoKg || null;
            datos.comprador = comprador;
            datos.valorVenta = valorVenta;
            datos.pesoVenta = pesoVenta;
          } else {
            const causa = (this.container.querySelector('#input-extraer-causa-muerte')?.value || '').trim() || 'Causa no especificada';
            datos.motivoMuerte = causa;
          }

          if (this.onExtraer) {
            this.onExtraer(this.animal, datos);
          }
          this.modalExtraerAbierto = false;
          this.cerrar();
        });
      }
    }
  }
}


// ============================================================================
// ARCHIVO: frontend/src/components/PanelAlertas.js
// ============================================================================
/**
 * GANADERO AD - PANEL DE ALERTAS ZOOTÉCNICAS E IA
 * Notificaciones destacadas para animales improductivos, sanidad y auditoría.
 */



class PanelAlertas {
  constructor({ containerId, getAnimales, onAccionZootecnica }) {
    this.container = document.getElementById(containerId);
    this.getAnimales = getAnimales;
    this.onAccionZootecnica = onAccionZootecnica;
    this.filtroSeveridad = 'todas'; // 'todas' | 'critica' | 'advertencia' | 'sanidad_preventiva'
    this.alertasResueltas = new Set();
  }

  init() {
    this.render();
  }

  resolverAlerta(id) {
    this.alertasResueltas.add(id);
    this.render();
  }

  obtenerAlertas() {
    const todos = this.getAnimales ? this.getAnimales() : [];
    const lista = detectarAlertasZootecnicas(todos);
    return lista.filter((a) => !this.alertasResueltas.has(a.id));
  }

  render() {
    if (!this.container) return;

    const alertas = this.obtenerAlertas();
    const criticas = alertas.filter((a) => a.severidad === 'critica');
    const advertencias = alertas.filter((a) => a.severidad === 'advertencia');
    const sanidad = alertas.filter((a) => a.severidad === 'sanidad_preventiva');

    let mostradas = alertas;
    if (this.filtroSeveridad !== 'todas') {
      mostradas = alertas.filter((a) => a.severidad === this.filtroSeveridad);
    }

    this.container.innerHTML = `
      <div class="space-y-4">
        <!-- HEADER DE ALERTAS INTELIGENTES -->
        <div class="bovi-module-header p-5 rounded-2xl shadow-xl border border-slate-800">
          <div class="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
            <div class="flex items-center gap-3">
              <div class="w-12 h-12 rounded-2xl bg-rose-500/20 text-rose-700 border border-rose-500/30 flex items-center justify-center text-2xl shadow">
                🚨
              </div>
              <div>
                <h2 class="text-base sm:text-xl font-black tracking-tight flex items-center gap-2">
                  Panel de Alertas Inteligentes & Auditoría IA
                  <span class="text-[10px] px-2.5 py-0.5 rounded-full bg-rose-600 text-white font-mono font-bold">${alertas.length} ACTIVAS</span>
                </h2>
                <p class="text-xs text-slate-600">Detección de animales improductivos, días abiertos excesivos y vacas próximas al secado.</p>
              </div>
            </div>

            <!-- FILTROS POR SEVERIDAD -->
            <div class="flex items-center gap-1.5 bg-slate-800/80 p-1.5 rounded-xl border border-slate-700 text-xs w-full md:w-auto overflow-x-auto">
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'todas' ? 'bg-emerald-600 text-white' : 'text-slate-600 hover:text-white'}" data-sev="todas">
                Todas (${alertas.length})
              </button>
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'critica' ? 'bg-rose-600 text-white' : 'text-rose-700 hover:text-white'}" data-sev="critica">
                🔴 Críticas (${criticas.length})
              </button>
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'advertencia' ? 'bg-amber-600 text-white' : 'text-amber-700 hover:text-white'}" data-sev="advertencia">
                🟡 Advertencias (${advertencias.length})
              </button>
              <button class="btn-filtro-alerta px-3 py-1.5 rounded-lg font-bold transition whitespace-nowrap ${this.filtroSeveridad === 'sanidad_preventiva' ? 'bg-sky-600 text-white' : 'text-sky-700 hover:text-white'}" data-sev="sanidad_preventiva">
                🔵 Secado 7 Meses (${sanidad.length})
              </button>
            </div>
          </div>

          <!-- RESUMEN DE LOS 4 PILARES ZOOTÉCNICOS REQUERIDOS -->
          <div class="grid grid-cols-2 lg:grid-cols-4 gap-3 mt-5 pt-4 border-t border-slate-800 text-xs">
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-600 block text-[10px] uppercase font-bold">1. Crecimiento (GDP &lt; 300g/d)</span>
              <span class="text-xl font-black text-rose-700">
                ${alertas.filter((a) => a.tipo === 'crecimiento_bajo_gdp').length} <span class="text-xs text-slate-600 font-normal">animales</span>
              </span>
            </div>
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-600 block text-[10px] uppercase font-bold">2. Vacas Vacías (&gt; 200 Días)</span>
              <span class="text-xl font-black text-rose-700">
                ${alertas.filter((a) => a.tipo === 'vaca_vacia_dias_abiertos').length} <span class="text-xs text-slate-600 font-normal">vientres</span>
              </span>
            </div>
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-600 block text-[10px] uppercase font-bold">3. Novillas Vacías (&gt; 36 Meses)</span>
              <span class="text-xl font-black text-amber-700">
                ${alertas.filter((a) => a.tipo === 'novilla_vacia_edad').length} <span class="text-xs text-slate-600 font-normal">novillas</span>
              </span>
            </div>
            <div class="bg-slate-900/80 p-3 rounded-xl border border-slate-800">
              <span class="text-slate-600 block text-[10px] uppercase font-bold">4. Secado Gestación (~7 Meses)</span>
              <span class="text-xl font-black text-sky-700">
                ${alertas.filter((a) => a.tipo === 'secado_7_meses').length} <span class="text-xs text-slate-600 font-normal">vacas</span>
              </span>
            </div>
          </div>
        </div>

        <!-- LISTA DE TARJETAS DE ALERTA -->
        <div class="space-y-3">
          ${mostradas.length > 0 ? mostradas.map((a) => this.renderTarjeta(a)).join('') : `
            <div class="bg-white p-12 rounded-2xl border border-slate-200 text-center shadow-sm">
              <div class="w-16 h-16 mx-auto mb-3 rounded-2xl bg-emerald-100 text-emerald-700 flex items-center justify-center text-3xl">
                ✨
              </div>
              <h3 class="text-base font-black text-slate-800">Sin Alertas en esta Categoría</h3>
              <p class="text-xs text-slate-600 mt-1 max-w-md mx-auto">Los animales cumplen los estándares zootécnicos establecidos.</p>
            </div>
          `}
        </div>
      </div>
    `;

    this.attachEvents();
  }

  renderTarjeta(a) {
    let badge = '';
    let border = 'border-slate-200';
    let bgHeader = 'bg-slate-50';

    if (a.severidad === 'critica') {
      badge = '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-rose-100 text-rose-800 border border-rose-200">Crítica</span>';
      border = 'border-rose-200';
      bgHeader = 'bg-rose-50/50';
    } else if (a.severidad === 'advertencia') {
      badge = '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-amber-100 text-amber-800 border border-amber-200">Advertencia</span>';
      border = 'border-amber-200';
      bgHeader = 'bg-amber-50/50';
    } else {
      badge = '<span class="px-2.5 py-0.5 rounded-full text-[10px] font-black uppercase bg-sky-100 text-sky-800 border border-sky-200">Preventiva</span>';
      border = 'border-sky-200';
      bgHeader = 'bg-sky-50/50';
    }

    return `
      <div class="bg-white rounded-2xl border ${border} shadow-md hover:shadow-lg transition overflow-hidden">
        <div class="${bgHeader} p-4 border-b border-slate-100 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
          <div class="flex items-center gap-3">
            <span class="font-mono font-black text-slate-800 bg-white px-3 py-1.5 rounded-xl border border-slate-200 text-sm shadow-sm">
              Tag: ${a.tag}
            </span>
            <div>
              <div class="flex items-center gap-2">
                <span class="font-bold text-slate-800 text-sm">${a.nombre}</span>
                <span class="text-xs text-slate-600">• ${a.categoria}</span>
                <span class="text-xs text-slate-600">• ${a.lote}</span>
              </div>
              <h4 class="font-black text-slate-800 text-sm mt-0.5">${a.titulo}</h4>
            </div>
          </div>
          <div>${badge}</div>
        </div>

        <div class="p-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div class="space-y-1.5 max-w-2xl">
            <p class="text-xs text-slate-600 leading-relaxed">${a.mensaje}</p>
            <div class="flex flex-wrap items-center gap-2 text-xs pt-1">
              <span class="bg-slate-100 px-2 py-0.5 rounded font-mono text-slate-700 font-bold">Detectado: <strong>${a.valorMedido}</strong></span>
              <span class="bg-slate-100 px-2 py-0.5 rounded font-mono text-slate-700 font-bold">Meta: <strong>${a.valorLimite}</strong></span>
              <span class="text-emerald-700 font-medium">💡 ${a.accionRecomendada}</span>
            </div>
          </div>

          <div class="flex items-center gap-2 w-full md:w-auto justify-end border-t md:border-t-0 pt-3 md:pt-0">
            <button class="btn-resolver-alerta px-3.5 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs border border-slate-200 transition" data-id="${a.id}">
              ✓ Marcar Resuelta
            </button>
            <button class="btn-accion-directa px-4 py-2 bg-slate-900 hover:bg-slate-800 text-slate-800 font-bold rounded-xl text-xs shadow transition active:scale-95" data-animal="${a.animalId}" data-tipo="${a.tipo}">
              ⚡ Tomar Acción
            </button>
          </div>
        </div>
      </div>
    `;
  }

  attachEvents() {
    this.container.querySelectorAll('.btn-filtro-alerta').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        this.filtroSeveridad = e.currentTarget.getAttribute('data-sev');
        this.render();
      });
    });

    this.container.querySelectorAll('.btn-resolver-alerta').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        this.resolverAlerta(e.currentTarget.getAttribute('data-id'));
      });
    });

    this.container.querySelectorAll('.btn-accion-directa').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const animalId = e.currentTarget.getAttribute('data-animal');
        const tipo = e.currentTarget.getAttribute('data-tipo');
        if (this.onAccionZootecnica) {
          this.onAccionZootecnica({ animalId, tipo });
        }
      });
    });
  }
}


