      getNutricion: () => this.state.nutricion || [],
      getPesajes: () => this.state.pesajes || [],
      onGuardarPlan: (registro) => this.guardarPlanNutricion(registro),
      onEliminarRegistro: (tag) => this.eliminarPlanNutricion(tag),
